Object.assign(window.TEM8_DICTIONARY, {"piqued":{"media":{"uk":"media/uk/piqued__gb_1.mp3","us":"media/us/piqued__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（常指为小事）生气的，恼怒的，愠怒的","en":"If someone is piqued, they are offended or annoyed, often by something that is not very important.","ex":{"en":"Granny was astounded and a little piqued, I think, because it had all been arranged without her knowledge","cn":"奶奶很吃惊，我想还有点儿生气，因为所有这些安排都没有告诉过她。"}}]},"examples":[{"en":"She couldn't help feeling a little piqued by his lack of interest.","cn":"她不禁对他的淡漠感到有些不乐。"}],"oxford":{"phon":"piːkt","pos":"adjective","senses":[{"en":"annoyed or upset","cn":"使愤恨；使恼怒","ex":{"en":"She couldn't help feeling a little piqued by his lack of interest.","cn":"她不禁对他的淡漠感到有些不悦。"}}]}},"pie":{"oxford":{"phon":"paɪ","pos":"noun","senses":[{"en":"a baked dish of fruit or meat and/or vegetables with pastry on the bottom, sides and top","cn":"派，馅饼（以水果、肉或蔬菜作馅料烤制而成）","ex":{"en":"a slice of apple pie","cn":"一块苹果派"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"馅饼，派（内有肉、蔬菜或水果的西式点心）","en":"A pie consists of meat, vegetables, or fruit baked in pastry.","ex":{"en":"...a pork pie.","cn":"猪肉馅饼"}},{"pos":"PHRASE 短语","cn":"难以付诸实施的构想（或计划）；渺茫的希望；空口的许诺","en":"If you describe an idea, plan, or promise of something good as pie in the sky, you mean that you think that it is very unlikely to happen.","ex":{"en":"The true regeneration of devastated Docklands seemed like pie in the sky","cn":"遭毁坏码头区的真正重建看起来希望渺茫。"}},{"pos":"","cn":"","en":"to eat humble pie→see: ;"}]},"media":{"uk":"media/uk/pie__gb_1.mp3","us":"media/us/pie__us_1.mp3","img":["media/ldoce/img/apple_pie.jpg"]},"examples":[{"en":"This talk of moving to Australia is all just pie in the sky.","cn":"移居澳大利亚之说纯属异想天开。"},{"en":"Help yourself to some more pie.","cn":"请随意再吃些果馅饼吧。"}]},"piles":{"media":{"uk":"media/uk/piles__gb_1.mp3","us":"media/us/piles__us_1.mp3"},"oxford":{"phon":"paɪlz","pos":"noun","senses":[{"en":"veins at or near the anus that have become painful and swollen (= larger than normal)","cn":"痔；痔疮"}]}},"pip":{"media":{"uk":"media/uk/pip__gb_1.mp3","us":"media/us/pip__us_1.mp3"},"oxford":{"phon":"pɪp","pos":"noun","senses":[{"en":"the small hard seed that is found in some types of fruit","cn":"（某些水果的）种子，籽","lab":"especially British English","ex":{"en":"an apple/orange pip","cn":"苹果籽；橙子籽"}},{"en":"a series of short high sounds, especially those used when giving the exact time on the radio","cn":"嘟嘟声；（尤指电台的）报时信号","g":"[plural]","lab":"British English","ex":{"en":"The news will follow the pips at six o’clock.","cn":"消息将在六点钟跟随点子发布。"}},{"en":"one of the small round marks showing the value on dice and dominoes; one of the marks showing the value and suit of a playing card","cn":"（色子、骨牌、纸牌上的）点","lab":"North American English"},{"en":"to beat somebody in a race, competition, etc. by only a small amount or at the last moment","cn":"以微弱优势击败；险胜；终于战胜","ex":{"en":"She pipped her rival for the gold medal.","cn":"她险胜对手，夺得金牌。"},"pos":"verb"},{"en":"the central character in the novel Great Expectations by Charles Dickens","cn":"点子：查尔斯·狄更斯（Charles Dickens）的小说《远大前程》（Great Expectations）中的中心人物","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（苹果、柑橘、梨等的）种子，籽","en":"Pips are the small hard seeds in a fruit such as an apple, orange, or pear."},{"pos":"VERB 动词","cn":"以微弱优势打败；险胜","en":"If someone is pipped to something such as a prize or an award, they are defeated by only a small amount.","ex":{"en":"It's still possible for the losers to be pipped by West Germany for a semi-final place","cn":"失利者仍有可能在争夺半决赛权时被西德队击败。"}},{"pos":"N-PLURAL 复数名词","cn":"（英国广播中的）报时信号","en":"In Britain, the pips on the radio are a series of short, high-pitched sounds that are used as a time signal."},{"pos":"N-PLURAL 复数名词","cn":"（英国公用电话提示需要投入硬币时的）嘟嘟声","en":"In Britain, when you make a telephone call from a public telephone, the pips are a signal that you need to put in more money."},{"pos":"PHRASE 短语","cn":"（在竞赛等中）于最后一刻击败，险胜","en":"If someone is pipped at the post or pipped to the post they are just beaten in a competition or in a race to achieve something.","ex":{"en":"I didn't want us to be pipped to the post.","cn":"我不希望我们在最后一刻落败。"}}]},"examples":[{"en":"He was pipped at/to the post for the top award.","cn":"他到终点时以些微之差被超越，失去了冠军。"},{"en":"She pipped her rival for the gold medal.","cn":"她险胜对手，夺得金牌。"}]},"pitched":{"media":{"uk":"media/uk/pitched__gb_1.mp3","us":"media/us/pitched__us_1.mp3"},"oxford":{"phon":"pɪtʃt","pos":"adjective","senses":[{"en":"sloping; not flat","cn":"倾斜的","ex":{"en":"steeply pitched roofs","cn":"陡峭的屋顶"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（屋顶）斜的","en":"A pitched roof is one that slopes as opposed to one that is flat.","ex":{"en":"...a rather quaint lodge with a steeply-pitched roof.","cn":"屋顶大幅倾斜的相当老式别致的小屋"}}]}},"pig":{"oxford":{"phon":"pɪɡ","pos":"noun","senses":[{"en":"an animal with pink, black or brown skin, short legs, a broad nose and a short curly tail. Pigs are kept on farms for their meat (called pork) or live in the wild.","cn":"猪","lab":"especially in North American English","ex":{"en":"a pig farmer","cn":"养猪的农民"}},{"en":"a person who you find unpleasant or offensive; a person who you think is dirty or greedy","cn":"令人不快（或讨厌）的人；肮脏（或贪婪）的人","lab":"informal, disapproving，，","ex":{"en":"Arrogant pig!","cn":"傲慢的家伙！"}},{"en":"an offensive word for a police officer","cn":"（对警察的蔑称）","lab":"slang, offensive，，"},{"en":"to eat too much of something","cn":"吃得过量；大吃特吃","ex":{"en":"I had a whole box of chocolates and pigged the lot!","cn":"我把一整盒巧克力吃了个精光！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猪","en":"A pig is a pink or black animal with short legs and not much hair on its skin. Pigs are often kept on farms for their meat, which is called pork, ham, bacon, or gammon.","ex":{"en":"...the grunting of the pigs.","cn":"猪的呼噜声"}},{"pos":"N-COUNT 可数名词","cn":"猪猡；讨嫌的人；（尤指）贪婪的人，苛刻的人","en":"If you call someone a pig, you think that they are unpleasant in some way, especially that they are greedy or unkind."},{"pos":"N-SING 单数名词","cn":"难干的活；难做的事","en":"If you say that something is, for example, a pig of a job, you mean it is very difficult.","ex":{"en":"According to the British show jumping team manager, 'It's a pig of a course — much too big and also very technical.'","cn":"据英国场地障碍赛马队教练说，“整个赛场太大，对技术的要求也高，比赛起来很困难。”"}},{"pos":"VERB 动词","cn":"使贪婪地吃；使拼命大吃","en":"If you say that people are pigging themselves, you are criticizing them for eating a very large amount at one meal.","ex":{"en":"After pigging herself on ice cream she went upstairs.","cn":"大吃特吃了一通冰激凌之后她上了楼。"}},{"pos":"PHRASE 短语","cn":"粗制滥造；把…弄糟","en":"If you make a pig's ear of something you are doing, you do it very badly.","ex":{"en":"He and Dermott Reeve almost made a complete pig's ear of the final push for victory.","cn":"他和德莫特·里夫几乎把获胜的最后一把努力彻底搞砸了。"}},{"pos":"PHRASE 短语","cn":"不可能的事；异想天开","en":"If you say 'pigs might fly' after someone has said that something might happen, you are emphasizing that you think it is very unlikely.","ex":{"en":"'There's a chance he won't get involved in this, of course.' — 'And pigs might fly.'","cn":"“当然，他还是有可能不插手此事的。”——“是啊，太阳还能打西边出呢。”"}},{"pos":"PHRASE 短语","cn":"大吃特吃；吃得过量","en":"If you say that someone is making a pig of themselves, you are criticizing them for eating a very large amount at one meal.","ex":{"en":"I'm afraid I made a pig of myself at dinner.","cn":"恐怕我晚餐时吃得太多了。"}},{"pos":"","cn":"","en":"相关词组：pig out"}]},"media":{"uk":"media/uk/pig__gb_1.mp3","us":"media/us/pig__us_1.mp3"},"examples":[{"en":"‘With a bit of luck, we'll be finished by the end of the year.’ ‘Yes, and pigs might fly!’ “","cn":"运气不错的话，我们年底就能完成。” “是啊，太阳能打西边出嘛！”"},{"en":"Don't give me cakes — I'll just pig myself.","cn":"可别给我拿糕点，那我会吃个没够的。"}]},"pill":{"oxford":{"phon":"pɪl","pos":"noun","senses":[{"en":"a small flat round piece of medicine that you swallow whole, without biting it","cn":"药丸；药片","g":"[countable]","lab":"informal","ex":{"en":"a vitamin pill","cn":"维生素片"}},{"en":"a pill that some women take to prevent them becoming pregnant","cn":"口服避孕药","g":"[singular]","ex":{"en":"the contraceptive pill","cn":"避孕药丸"}},{"en":"an annoying person","cn":"讨厌的人；讨厌鬼","g":"[countable]","lab":"North American English"},{"en":"to become covered in very small balls of fibre","cn":"起球；结绒","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"药丸；丸剂","en":"Pills are small solid round masses of medicine or vitamins that you swallow without chewing.","ex":{"en":"Why do I have to take all these pills?","cn":"我为什么非得服下所有这些药丸呢？"}},{"pos":"N-SING 单数名词","cn":"（女用）口服避孕药","en":"If a woman is on the pill, she takes a special pill that prevents her from becoming pregnant.","ex":{"en":"She had been on the pill for three years.","cn":"她吃口服避孕药已有3年。"}},{"pos":"PHRASE 短语","cn":"不得不承受的苦事；不得不接受的现实","en":"If a person or group has to accept a failure or an unpleasant piece of news, you can say that it was a bitter pill or a bitter pill to swallow .","ex":{"en":"You're too old to be given a job. That's a bitter pill to swallow.","cn":"你年龄太大了，没人愿意再给工作，这是你不得不接受的现实。"}},{"pos":"PHRASE 短语","cn":"把苦药包上糖衣；使不愉快的事变得较易接受","en":"If someone does something to sweeten the pill or sugar the pill, they do it to make some unpleasant news or an unpleasant measure more acceptable.","ex":{"en":"He sweetened the pill by increasing wages, although by slightly less than he raised prices.","cn":"他提高了工资以使人们更易接受，尽管涨幅略低于他的价格升幅。"}}]},"media":{"uk":"media/uk/pill__gb_1.mp3","us":"media/us/pill__us_1.mp3","img":["media/ldoce/img/pills.jpg"]},"examples":[{"en":"to be/go on the pill","cn":"在服用避孕药"},{"en":"a vitamin pill","cn":"维生素片"}]},"piano":{"media":{"img":["media/ldoce/img/piano.jpg","media/pic/pianos_musicalinstruments_comp.jpg"],"uk":"media/uk/piano__gb_1.mp3","us":"media/us/piano__us_1.mp3"},"oxford":{"phon":"piˈænəʊ","pos":"noun","senses":[{"en":"a large musical instrument played by pressing the black and white keys on the keyboard. The sound is produced by small hammers hitting the metal strings inside the piano.","cn":"钢琴","ex":{"en":"to play the piano","cn":"弹钢琴"}},{"en":"played or sung quietly","cn":"轻柔地；安静地；弱","pos":"adjective"},{"en":"played or sung quietly","cn":"轻柔地；安静地；弱","pos":"adverb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"钢琴","en":"A piano is a large musical instrument with a row of black and white keys. When you press these keys with your fingers, little hammers hit wire strings inside the piano which vibrate to produce musical notes.","ex":{"en":"I taught myself how to play the piano","cn":"我自学了弹钢琴。"}},{"pos":"ADV 副词","cn":"轻轻地；微弱地","en":"A piece of music that is played piano is played quietly."}]},"examples":[{"en":"Ravel's piano concerto in G","cn":"拉威尔的 G 大调钢琴协奏曲"},{"en":"playing jazz on the piano","cn":"用钢琴弹奏爵士乐"}]},"picture":{"media":{"uk":"media/uk/picture__gb_1.mp3","us":"media/us/picture__us_1.mp3"},"oxford":{"phon":"ˈpɪktʃə(r)","pos":"noun","senses":[{"en":"a painting or drawing, etc. that shows a scene, a person or thing","cn":"图画；绘画","g":"[countable]","sc":"painting/drawing","ex":{"en":"He likes books with lots of pictures in them.","cn":"他喜欢看有大量插图的书。"}},{"en":"a photograph","cn":"相片；照片","g":"[countable]","sc":"photograph","ex":{"en":"to take a picture","cn":"拍照"}},{"en":"an image on a television screen","cn":"电视图像","g":"[countable]","sc":"on TV","ex":{"en":"harrowing television pictures of the famine","cn":"电视上悲惨的饥荒画面"}},{"en":"a description that gives you an idea in your mind of what something is like","cn":"描绘；描述","g":"[countable, usually singular]","sc":"description","ex":{"en":"We've only got scraps of information, not the full picture.","cn":"我们只有零星的信息，不知道全貌。"}},{"en":"a mental image or memory of something","cn":"头脑中的情景；记忆；印象","g":"[countable, usually singular]","sc":"mental image","ex":{"en":"I have a vivid picture of my grandfather smiling down at me when I was very small.","cn":"我清楚地记得很小的时候祖父低头向我微笑的情景。"}},{"en":"the general situation relating to somebody/something","cn":"状况；情形；形势","g":"[singular]","sc":"general situation","ex":{"en":"Just a few years ago the picture was very different.","cn":"几年前的情况就大不相同。"}},{"en":"a film","cn":"电影；影片","g":"[countable]","lab":"especially North American English","sc":"movies","ex":{"en":"The movie won nine Academy Awards, including Best Picture.","cn":"这部电影荣获九项奥斯卡金像奖，包括最佳影片奖。"}},{"en":"the cinema","cn":"电影院","g":"[plural]","lab":"old-fashioned, informal，，","sc":"movies","ex":{"en":"Shall we go to the pictures tonight?","cn":"今晚我们去看电影好吗？"}},{"en":"to imagine somebody/something; to create an image of somebody/something in your mind","cn":"想象；设想；忆起","sc":"imagine","ex":{"en":"I could picture the scene clearly.","cn":"我能清楚地想象这个场面。"},"pos":"verb"},{"en":"to describe or present somebody/something in a particular way","cn":"描述；描写","g":"[often passive]","sc":"describe","ex":{"en":"Before the trial Liz had been pictured as a frail woman dominated by her husband.","cn":"审讯之前，利兹被描绘成受丈夫操纵的孱弱女子。"},"pos":"verb"},{"en":"to show somebody/something in a photograph or picture","cn":"显示在照片上；用图片显示","g":"[usually passive]","sc":"show in photograph","ex":{"en":"She is pictured here with her parents.","cn":"这张照片是她和父母的合影。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图画；绘画；图片","en":"A picture consists of lines and shapes which are drawn, painted, or printed on a surface and show a person, thing, or scene.","ex":{"en":"A picture of Rory O'Moore hangs in the dining room at Kildangan.","cn":"一幅罗里·奥穆尔的画像挂在基尔丹根的餐厅里。"}},{"pos":"N-COUNT 可数名词","cn":"照片","en":"A picture is a photograph.","ex":{"en":"The tourists have nothing to do but take pictures of each other","cn":"游客无事可做，只能互相拍照。"}},{"pos":"N-COUNT 可数名词","cn":"（电视）图像，画面","en":"Television pictures are the scenes which you see on a television screen.","ex":{"en":"...heartrending television pictures of human suffering.","cn":"令人心碎的人类遭受苦难的电视画面"}},{"pos":"VERB 动词","cn":"（在报纸、杂志等上）登载…的照片（或图片）","en":"To be pictured somewhere, for example in a newspaper or magazine, means to appear in a photograph or picture.","ex":{"en":"The golfer is pictured on many of the front pages, kissing his trophy as he holds it aloft.","cn":"许多报纸的头版上都刊登了那个高尔夫球手高高举起奖杯亲吻的照片。"}},{"pos":"N-COUNT 可数名词","cn":"影片；电影","en":"You can refer to a film as a picture .","ex":{"en":"Warner Communications Inc. has refused to distribute the picture in the United States.","cn":"华纳通信公司已拒绝在美国发行这部电影。"}},{"pos":"N-PLURAL 复数名词","cn":"电影院","en":"If you go to the pictures, you go to a cinema to see a film.","ex":{"en":"We're going to the pictures tonight","cn":"我们今晚要去看电影。"}},{"pos":"N-COUNT 可数名词","cn":"想象；印象；心中的形象;头脑中的情景","en":"If you have a picture of something in your mind, you have a clear idea or memory of it in your mind as if you were actually seeing it.","ex":{"en":"They have in their mind a picture of what an alcoholic should look like","cn":"他们的心中有一个酒鬼应有的样子。"}},{"pos":"VERB 动词","cn":"想象；设想","en":"If you picture something in your mind, you think of it and have such a clear memory or idea of it that you seem to be able to see it.","ex":{"en":"He pictured her with long black braided hair","cn":"他想象她留着黑油油的长辫子的样子。"}},{"pos":"N-COUNT 可数名词","cn":"描述；描绘；写照","en":"A picture of something is a description of it or an indication of what it is like.","ex":{"en":"I'll try and give you a better picture of what the boys do","cn":"我会试着更清楚地向你描述一下这些男孩子都干些什么。"}},{"pos":"N-SING 单数名词","cn":"事态；情况；局面","en":"When you refer to the picture in a particular place, you are referring to the situation there.","ex":{"en":"But as with other charitable bodies, these figures mask the true picture","cn":"但和其他慈善机构一样，这些数字掩盖了实情。"}},{"pos":"PHRASE 短语","cn":"（尤指通过他人描述）弄明白情况，了解情形","en":"If you get the picture, you understand the situation, especially one which someone is describing to you.","ex":{"en":"Luke never tells you the whole story, but you always get the picture.","cn":"卢克从不告诉你事情的来龙去脉，但你总会弄明白是怎么回事。"}},{"pos":"PHRASE 短语","cn":"牵涉其中/不涉其中；在局内/在局外","en":"If you say that someone is in the picture, you mean that they are involved in the situation that you are talking about. If you say that they are out of the picture, you mean that they are not involved in the situation.","ex":{"en":"Meyerson is back in the picture after disappearing in July","cn":"迈耶森在7月份消失后现在又掺和了进来了。"}},{"pos":"PHRASE 短语","cn":"（形容模样）健康的化身/痛苦的典型","en":"You use picture to describe what someone looks like. For example, if you say that someone is a picture of health or the picture of misery, you mean that they look extremely healthy or extremely miserable.","ex":{"en":"We found her standing on a chair, the picture of terror, screaming hysterically.","cn":"我们发现她站在一把椅子上，满脸恐惧地发出歇斯底里的尖叫。"}},{"pos":"PHRASE 短语","cn":"使了解内情；向…介绍情况","en":"If you put someone in the picture, you tell them about a situation which they need to know about.","ex":{"en":"Has Inspector Fayard put you in the picture?","cn":"法亚尔督察把情况都告诉你了吗？"}}]},"examples":[{"en":"Just to put you in the picture — there have been a number of changes here recently.","cn":"只是让你了解一下情况吧，最近这里出现了许多变化。"},{"en":"I have a vivid picture of my grandfather smiling down at me when I was very small.","cn":"我清楚地记得很小的时候祖父低头向我微笑的情景。"}]},"pic":{"oxford":{"phon":"pɪk","pos":"noun","senses":[{"en":"a picture","cn":"图片；画片"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"影片；电影","en":"A pic is a cinema film.","ex":{"en":"'Angels with Dirty Faces' is a Cagney gangster pic.","cn":"《一世之雄》是一部由卡格尼主演的黑帮片。"}},{"pos":"N-COUNT 可数名词","cn":"照片；图片","en":"A pic is a photograph.","ex":{"en":"Photographer Weegee shot to fame with his shocking pics of New York crime in the 30s.","cn":"摄影师维吉以拍摄30年代纽约罪案的骇人照片而声名鹊起。"}}]},"media":{"uk":"media/uk/pic__gb_1.mp3","us":"media/us/pic__us_1.mp3"}},"pit":{"oxford":{"phon":"pɪt","pos":"noun","senses":[{"en":"a large deep hole in the ground","cn":"深洞；深坑","g":"[countable]","lab":"figurative","sc":"deep hole","ex":{"en":"We dug a deep pit in the yard.","cn":"我们在院子中挖了个深洞。"}},{"en":"a deep hole in the ground from which minerals are dug out","cn":"矿井","g":"[countable]","sc":"deep hole","ex":{"en":"a chalk/gravel pit","cn":"白垩／沙砾矿坑"}},{"en":"a place underground where coal is dug","cn":"煤矿","g":"[countable]","lab":"British English","sc":"mine","ex":{"en":"pit closures","cn":"煤矿关闭"}},{"en":"a small shallow hole in the surface of something, especially a mark left on the surface of the skin by some disease, such as chickenpox","cn":"麻子；痘瘢","g":"[countable]","sc":"in skin"},{"en":"a hard shell containing the nut or seed in the middle of some types of fruit","cn":"果核","g":"[countable]","lab":"especially North American English","sc":"in fruit","ex":{"en":"a peach pit","cn":"桃核"}},{"en":"a place near the track where cars can stop for fuel, new tyres, etc. during a race","cn":"（赛车道旁的）维修站","g":"[plural]","lab":"British English","sc":"in motor racing"},{"en":"the place in a theatre just in front of the stage where the orchestra sits and plays for an opera, a ballet, etc.","cn":"乐池，乐队席（舞台前乐队演奏的地方）","g":"[countable]","sc":"in theatre"},{"en":"an armpit (= the part of the body under the arm where it joins the shoulder)","cn":"（人的）腋窝","g":"[countable]","lab":"North American English, informal，，","sc":"part of body"},{"en":"the area of a stock exchange where a particular product is traded","cn":"（交易所中某一商品的）交易场所","g":"[countable]","lab":"North American English","sc":"in business","ex":{"en":"the corn pit","cn":"玉米交易厅"}},{"en":"to make marks or holes on the surface of something","cn":"使…表面有斑点；在…上打洞","sc":"make holes","ex":{"en":"Smallpox scars had pitted his face.","cn":"他满脸天花疤痕。"},"pos":"verb"},{"en":"to remove the stone from the inside of a fruit","cn":"去掉…的果核","lab":"British English also","sc":"fruit","ex":{"en":"pitted olives","cn":"去核橄榄"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"煤矿；矿井","en":"A pit is a coal mine.","ex":{"en":"It was a better community then when all the pits were working.","cn":"所有的煤矿都在开工的那个时候，这个社区的情况要更好一些。"}},{"pos":"N-COUNT 可数名词","cn":"（地面的）坑，洼；（地下的）穴，洞","en":"A pit is a large hole that is dug in the ground.","ex":{"en":"Eric lost his footing and began to slide into the pit.","cn":"埃里克一脚踩空，开始往坑里滑。"}},{"pos":"N-COUNT 可数名词","cn":"（挖出沙砾或黏土后留下的）坑，窑","en":"A gravel pit or clay pit is a very large hole that is left where gravel or clay has been dug from the ground.","ex":{"en":"This area of former farmland was worked as a gravel pit until 1964.","cn":"这块过去曾是农田的地1964年前一直被用作沙砾坑。"}},{"pos":"VERB 动词","cn":"使相斗；使对立；使竞争","en":"If two opposing things or people are pitted against one another, they are in conflict.","ex":{"en":"You will be pitted against people who are every bit as good as you are","cn":"你将和与你势均力敌的对手展开竞争。"}},{"pos":"N-PLURAL 复数名词","cn":"（赛车道旁的）检修加油站","en":"In motor racing, the pits are the areas at the side of the track where drivers stop to get more fuel and to repair their cars during races.","ex":{"en":"He moved quickly into the pits and climbed rapidly out of the car.","cn":"他迅速进入检修加油站，飞快地爬出赛车。"}},{"pos":"N-PLURAL 复数名词","cn":"极糟糕的情况","en":"If you describe something as the pits, you mean that it is extremely bad.","ex":{"en":"Mary Ann asked him how dinner had been. 'The pits,' he replied.","cn":"玛丽·安问他晚餐怎么样，他回答说：“糟透了。”"}},{"pos":"N-COUNT 可数名词","cn":"（水果或蔬菜的）核","en":"A pit is the stone of a fruit or vegetable."},{"pos":"PHRASE 短语","cn":"与…斗智","en":"If you pit your wits against someone, you compete with them in a test of knowledge or intelligence.","ex":{"en":"I'd like to pit my wits against the best.","cn":"我希望同最优秀的对手斗智。"}},{"pos":"PHRASE 短语","cn":"胸口；心窝","en":"If you have a feeling in the pit of your stomach, you have a tight or sick feeling in your stomach, usually because you are afraid or anxious.","ex":{"en":"I had a funny feeling in the pit of my stomach.","cn":"我心头有种怪怪的感觉。"}},{"pos":"","cn":"","en":"a bottomless pit→see: ;"}]},"media":{"uk":"media/uk/pit__gb_1.mp3","us":"media/us/pit__us_1.mp3"},"examples":[{"en":"Lawyers and accountants felt that they were being pitted against each other.","cn":"律师和会计师都觉得他们要一争高下。"},{"en":"He had a sudden sinking feeling in the pit of his stomach.","cn":"他内心深处突然有一种不祥之感。"}]},"pince-nez":{"oxford":{"phon":"ˌpæ̃s ˈneɪ","pos":"noun","senses":[{"en":"a pair of glasses, worn in the past, with a spring that fits on the nose, instead of parts at the sides that fit over the ears","cn":"（旧时的）夹鼻眼镜"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"夹鼻眼镜","en":"Pince-nez are old-fashioned glasses that consist of two lenses that fit tightly onto the top of your nose and do not have parts that rest on your ears.","ex":{"en":"His secretary was a tall woman in pince-nez.","cn":"他的秘书是位戴着夹鼻眼镜的高个女士。"}}]},"media":{"uk":"media/uk/pince_nez_1_gb_1.mp3","us":"media/us/pince_nez_1_us_1.mp3"}},"pipes":{"oxford":{"phon":"pɪp","pos":"noun","senses":[{"en":"the small hard seed that is found in some types of fruit （","cn":"某些水果的）种子，籽"},{"en":"( old-fashioned ) ( BrE ) a series of short high sounds, especially those used when giving the exact time on the radio","cn":"嘟嘟声；（尤指电台的）报时信号"}]},"media":{"uk":"media/uk/pip__gb_1.mp3","us":"media/us/pip__us_1.mp3"}},"pick":{"media":{"uk":"media/uk/pick__gb_1.mp3","us":"media/us/pick__us_1.mp3"},"oxford":{"phon":"pɪk","pos":"verb","senses":[{"en":"to choose somebody/something from a group of people or things","cn":"选择；挑选","g":"[transitive]","lab":"rather informal","ex":{"en":"Pick a number from one to twenty.","cn":"从一至二十中挑选一个数。"}},{"en":"to take flowers, fruit, etc. from the plant or the tree where they are growing","cn":"采；摘","g":"[transitive]","ex":{"en":"to pick grapes/strawberries/cotton","cn":"摘葡萄；摘草莓；摘棉花"}},{"en":"to pull or remove something or small pieces of something from something else, especially with your fingers","cn":"（用手指）摘掉，剔除，掐去","g":"[transitive]","ex":{"en":"She picked bits of fluff from his sweater.","cn":"她摘掉他毛衣上的绒毛。"}},{"en":"to play a musical instrument, especially a guitar, by pulling the strings with your fingers","cn":"弹，弹拨（乐器的弦）","g":"[intransitive, transitive]","lab":"North American English"},{"en":"an act of choosing something","cn":"挑选；选择","g":"[singular]","lab":"rather informal","ex":{"en":"Take your pick (= choose).","cn":"自己选吧。"},"pos":"noun"},{"en":"a person or thing that is chosen","cn":"选中的人（或物）","g":"[countable]","lab":"informal","ex":{"en":"She was his pick for best actress.","cn":"她是他选中的最佳女演员。"},"pos":"noun"},{"en":"the best thing or things in a group","cn":"精品；精华；最好的东西","g":"[singular]","lab":"rather informal","ex":{"en":"We're reviewing the pick of this month's new books.","cn":"我们正在做本月的精品新书评介。"},"pos":"noun"},{"en":"a large heavy tool that has a curved metal bar with sharp ends fixed at the centre to a wooden handle. It is used for breaking rocks or hard ground.","cn":"镐；尖嘴镐；鹤嘴锄","g":"[countable]","lab":"North American English also","ex":{"en":"picks and shovels","cn":"镐与平锹"},"pos":"noun"},{"en":"a plectrum (= a small piece of metal, plastic, etc. used for plucking the strings of a guitar or similar instrument)","cn":"（弹拨琴弦用的）琴拨，拨子","g":"[countable]","lab":"informal","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"挑选；选择","en":"If you pick a particular person or thing, you choose that one.","ex":{"en":"Mr Nowell had picked ten people to interview for six sales jobs in London","cn":"诺埃尔先生为伦敦的6个销售职位选出了10人进行面试。"}},{"pos":"N-SING 单数名词","cn":"精华；精品；精英","en":"You can refer to the best things or people in a particular group as the pick of that group.","ex":{"en":"The boys here are the pick of the under-15 cricketers in the country","cn":"这儿的男孩是全国15岁以下板球手中的佼佼者。"}},{"pos":"VERB 动词","cn":"采；摘","en":"When you pick flowers, fruit, or leaves, you break them off the plant or tree and collect them.","ex":{"en":"She used to pick flowers in the Cromwell Road","cn":"她过去常到克伦威尔路采花。"}},{"pos":"VERB 动词","cn":"拿取；挪移","en":"If you pick something from a place, you remove it from there with your fingers or your hand.","ex":{"en":"He picked the napkin from his lap and placed it alongside his plate","cn":"他拿起腿上的餐巾，放在盘子旁边。"}},{"pos":"VERB 动词","cn":"抠（鼻）；剔（牙）","en":"If you pick your nose or teeth, you remove substances from inside your nose or between your teeth.","ex":{"en":"Edgar, don't pick your nose, dear","cn":"埃德加，不要抠鼻子，宝贝儿。"}},{"pos":"VERB 动词","cn":"寻找…的口实；寻（衅）；找（碴儿）","en":"If you pick a fight or quarrel with someone, you deliberately cause one.","ex":{"en":"He picked a fight with a waiter and landed in jail","cn":"他找碴儿跟服务生打了一架，最后进了监狱。"}},{"pos":"VERB 动词","cn":"撬开（锁）；扒窃…中的东西","en":"If someone such as a thief picks a lock, they open it without a key, for example by using a piece of wire.","ex":{"en":"He picked each lock deftly, and rifled the papers within each drawer.","cn":"他熟练地撬开每一把锁，把每个抽屉里的文件都偷走了。"}},{"pos":"N-COUNT 可数名词","cn":"同 pickaxe","en":"A pick is the same as a pickaxe ."},{"pos":"PHRASE 短语","cn":"挑挑拣拣；挑三拣四；挑剔","en":"If you pick and choose, you carefully choose only things that you really want and reject the others.","ex":{"en":"As a vocational teacher I could pretty much pick and choose my work","cn":"作为一名职业教师，我几乎可以随意挑拣自己的工作。"}},{"pos":"PHRASE 短语","cn":"可从…中任意挑选","en":"If you have your pick of a group of things, you are able to choose any of them that you want.","ex":{"en":"Here is an actress who could have her pick of any part","cn":"这是一个角色任她挑选的女演员。"}},{"pos":"PHRASE 短语","cn":"任意挑选","en":"If you are told to take your pick, you can choose any one that you like from a group of things.","ex":{"en":"Accountants can take their pick of company cars","cn":"会计师可以任选配备的公车。"}},{"pos":"PHRASE 短语","cn":"择路而行；小心行路","en":"If you pick your way across an area, you walk across it very carefully in order to avoid obstacles or dangerous things.","ex":{"en":"The girls were afraid of snakes and picked their way along with extreme caution","cn":"女孩们害怕蛇，于是谨小慎微地择路而行。"}},{"pos":"","cn":"","en":"to pick someone's brains→see: ; to pick holes in something→see: ; to pick someone's pocket→see: ;"},{"pos":"PHRASE 短语","cn":"收拾残局；努力恢复正常","en":"When you pick up the pieces after a disaster, you do what you can to get the situation back to normal again.","ex":{"en":"Do we try and prevent problems or do we try and pick up the pieces afterwards?","cn":"我们是想要防患未然呢，还是想要事后收拾残局？"}},{"pos":"PHRASE 短语","cn":"加速","en":"When a vehicle picks up speed, it begins to move more quickly.","ex":{"en":"Brian pulled away slowly, but picked up speed.","cn":"布赖恩慢慢开动汽车，但很快就加速了。"}},{"pos":"","cn":"","en":"相关词组：pick at pick off pick on pick out pick over pick up"}]},"examples":[{"en":"All I seem to do is cook, wash and pick up after the kids.","cn":"烧饭、洗衣、跟在孩子屁股后头收拾东西，好像这就是我全部的活儿。"},{"en":"He picked out the tune on the piano with one finger.","cn":"他凭记忆用一个手指在钢琴上慢慢弹出了那支曲子。"}]},"pies":{"oxford":{"phon":"paɪ","pos":"noun","senses":[{"en":"fruit baked in a dish with pastry on the bottom, sides and top","cn":"果馅饼；果馅派"},{"en":"( especially BrE ) meat, vegetables, etc. baked in a dish with pastry on the bottom, sides and top","cn":"肉馅饼；蔬菜馅饼"}]}},"pitch-black":{"oxford":{"phon":"ˌpɪtʃ ˈblæk","pos":"adjective","senses":[{"en":"completely black or dark","cn":"漆黑的；乌黑的","ex":{"en":"a pitch-black night","cn":"漆黑的夜晚"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"漆黑的；乌黑的","en":"If a place or the night is pitch-black, it is completely dark.","ex":{"en":"...a cold pitch-black winter morning.","cn":"寒冷、漆黑的冬日早晨"}}]},"media":{"uk":"media/uk/pitch_black_1_gb_1.mp3","us":"media/us/pitch_black_1_us_1.mp3"},"examples":[{"en":"The lights were off and it was pitch-black.","cn":"灯灭了﹐一片漆黑。"}]},"pinched":{"media":{"uk":"media/uk/pinched__gb_1.mp3","us":"media/us/pinched__us_1.mp3"},"oxford":{"phon":"pɪntʃt","pos":"adjective","senses":[{"en":"pale and thin, especially because of illness, cold or worry","cn":"（因疾病、寒冷、愁苦等）苍白清瘦的，清癯的","ex":{"en":"His features were greyish and pinched.","cn":"他的脸色灰白，紧绷。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"消瘦苍白的；形容憔悴的","en":"If someone's face is pinched, it looks thin and pale, usually because they are ill or old.","ex":{"en":"Her face was pinched and drawn","cn":"她一脸苍白憔悴。"}}]},"examples":[{"en":"She had a small pinched face with sad eyes.","cn":"她瘦小的脸庞面容憔悴﹐眼神悲伤。"}]},"pillow":{"oxford":{"phon":"ˈpɪləʊ","pos":"noun","senses":[{"en":"a square or rectangular piece of cloth filled with soft material, used to rest your head on in bed","cn":"枕头","ex":{"en":"She lay back against the pillows.","cn":"她半躺半坐靠在枕头上。"}},{"en":"a cloth bag filled with soft material or feathers that is used, for example, to make a seat more comfortable","cn":"软垫；坐垫；靠垫","lab":"North American English"},{"en":"to rest something, especially your head, on an object","cn":"枕着（某物）","ex":{"en":"She lay on the grass, her head pillowed on her arms.","cn":"她头枕着胳膊躺在草地上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枕头","en":"A pillow is a rectangular cushion which you rest your head on when you are in bed."}]},"media":{"uk":"media/uk/pillow__gb_1.mp3","us":"media/us/pillow__us_1.mp3"},"examples":[{"en":"He lay back on the grass using his backpack as a pillow.","cn":"他用背包当枕头仰卧在草地上。"},{"en":"She lay on the grass, her head pillowed on her arms.","cn":"她头枕着胳膊躺在草地上。"}]},"pillows":{"oxford":{"phon":"ˈpɪləʊ","pos":"noun","senses":[{"en":"a square or rectangular piece of cloth filled with soft material, used to rest your head on in bed","cn":"枕头"},{"en":"( literary ) to rest sth, especially your head, on an object","cn":"枕着（某物）"}]}},"pin":{"media":{"uk":"media/uk/pin__gb_1.mp3","us":"media/us/pin__us_1.mp3","img":["media/ldoce/img/bowling.jpg"]},"oxford":{"phon":"pɪn","pos":"noun","senses":[{"en":"a short thin piece of stiff wire with a sharp point at one end and a round head at the other, used especially for fastening together pieces of cloth when sewing","cn":"大头针","sc":"for fastening/joining","ex":{"en":"Use pins to keep the patch in place while you sew it on.","cn":"打补丁时用大头针把布块别住。"}},{"en":"a short thin piece of stiff wire with a sharp point at one end and an item of decoration at the other, worn as jewellery","cn":"胸针；饰针","sc":"jewellery","ex":{"en":"a diamond pin","cn":"一枚钻石胸针"}},{"en":"a piece of jewellery with a pin on the back of it, that can be fastened to your clothes","cn":"饰针；胸针；领针","lab":"especially North American English","sc":"jewellery"},{"en":"a type of badge that is fastened with a pin at the back","cn":"（有别针的）徽章","lab":"especially North American English","sc":"badge","ex":{"en":"He supports the group and wears its pin on his lapel.","cn":"他支持这个团体，为此在翻领上佩戴该团体的徽章。"}},{"en":"a piece of steel used to support a bone in your body when it has been broken","cn":"（接骨用的）钢钉","sc":"medical","ex":{"en":"The pin in her spine will have to be changed as she grows.","cn":"随着她的成长，她脊柱上的钉子必须更换。"}},{"en":"one of the metal parts that stick out of an electric plug and fit into a socket","cn":"（插头的）销","sc":"electrical","ex":{"en":"a 2-pin plug","cn":"双芯插头"}},{"en":"a wooden or plastic object that is like a bottle in shape and that players try to knock down in games such as bowling","cn":"（保龄球等的）木瓶，瓶柱","sc":"in games"},{"en":"a stick with a flag on top of it, placed in a hole so that players can see where they are aiming for","cn":"旗杆","sc":"in golf","ex":{"en":"The ball stopped five feet short of the pin.","cn":"球停在距旗杆五英尺处。"}},{"en":"a person’s legs","cn":"（人的）双腿","g":"[plural]","lab":"informal","sc":"legs","ex":{"en":"He’s not as quick on his pins as he used to be.","cn":"他的动作不像以前那么快了。"}},{"en":"a small piece of metal on a hand grenade that stops it from exploding and is pulled out just before the hand grenade is thrown","cn":"（手榴弹上的）保险栓，保险针","sc":"on small bomb"},{"en":"to attach something onto another thing or fasten things together with a pin, etc.","cn":"（用大头钉等）固定，别上，钉住","sc":"fasten/join","ex":{"en":"She pinned the badge onto her jacket.","cn":"她把徽章别到外衣上。"},"pos":"verb"},{"en":"to make somebody unable to move by holding them or pressing them against something","cn":"使不能动弹；按住；钳住","sc":"prevent movement","ex":{"en":"They pinned him against a wall and stole his wallet.","cn":"他们把他按在墙上，偷走了他的钱包。"},"pos":"verb"},{"en":"a number given to you, for example by a bank, so that you can use a plastic card to take out money from a cash machine (the abbreviation for ‘personal identification number’)","cn":"个人识别码（全写为 personal identification number）"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"个人标志号；个人识别码；密码","en":"Someone's PIN or PIN number is a secret number which they can use, for example, with a bank card to withdraw money from a cash machine or ATM. PIN is an abbreviation for (缩略=) 'personal identification number'."}]},"examples":[{"en":"I need the up-to-date sales figures but I can never pin him down at the office.","cn":"我需要最新的销售数字，可就是不能在办公室找到他问清楚。"},{"en":"He supports the group and wears its pin on his lapel.","cn":"他支持这个团体，为此在翻领上佩戴该团体的徽章。"}]},"pigs":{"oxford":{"phon":"pɪɡ","pos":"noun","senses":[{"en":"an animal with pink, black or brown skin, short legs, a broad nose and a short tail which curls round itself. Pigs are kept on farms for their meat (called pork ) or live in the wild.","cn":"猪"},{"en":"( informal, disapproving ) an unpleasant or offensive person; a person who is dirty or greedy","cn":"令人不快（或讨厌）的人；贪婪（或肮脏）的人"}]}},"pinpoint":{"media":{"uk":"media/uk/pinpoint__gb_1.mp3","us":"media/us/pinpoint__us_1.mp3"},"oxford":{"phon":"ˈpɪnpɔɪnt","pos":"verb","senses":[{"en":"to find and show the exact position of somebody/something or the exact time that something happened","cn":"明确指出，确定（位置或时间）","ex":{"en":"He was able to pinpoint on the map the site of the medieval village.","cn":"他能在地图上准确找出那个中世纪村庄的位置。"}},{"en":"to be able to give the exact reason for something or to describe something exactly","cn":"准确解释（或说明）","ex":{"en":"The report pinpointed the areas most in need of help.","cn":"报告精确说明了亟待援助的地区。"}},{"en":"if something is done with pinpoint accuracy, it is done exactly and in exactly the right position","cn":"准确的；精确的","ex":{"en":"The pilots bombed strategic targets with pinpoint accuracy.","cn":"飞行员准确地轰炸了战略目标。"},"pos":"adjective"},{"en":"a very small area of something, especially light","cn":"（尤指光的）点","ex":{"en":"The star was little more than a pinpoint in the night sky.","cn":"这颗星星只不过是夜空中的一个小点。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"确认；准确解释（或说明）","en":"If you pinpoint the cause of something, you discover or explain the cause exactly.","ex":{"en":"It was almost impossible to pinpoint the cause of death.","cn":"几乎不可能确认死因。"}},{"pos":"VERB 动词","cn":"精确地确定（或指明）…的位置","en":"If you pinpoint something or its position, you discover or show exactly where it is.","ex":{"en":"I could pinpoint his precise location on a map","cn":"我能在地图上指明他的准确位置。"}},{"pos":"ADJ 形容词","cn":"定点的；定位精确的；非常精确的","en":"If something is placed with pinpoint accuracy, it is placed in exactly the right place or position.","ex":{"en":"...the pinpoint accuracy of the bombing campaigns.","cn":"战略性轰炸的精确定位"}}]},"examples":[{"en":"He was able to pinpoint on the map the site of the medieval village.","cn":"他能在地图上准确找出那个中世纪村庄的位置。"},{"en":"The report pinpointed the areas most in need of help.","cn":"报告精确说明了亟待援助的地区。"}]},"pitch":{"media":{"uk":"media/uk/pitch__gb_1.mp3","us":"media/us/pitch__us_1.mp3","img":["media/ldoce/img/pitch.jpg"]},"oxford":{"phon":"pɪtʃ","pos":"noun","senses":[{"en":"an area of ground specially prepared and marked for playing a sports game","cn":"（体育比赛的）场地；球场","g":"[countable]","lab":"British English","sc":"for sport","ex":{"en":"a football pitch","cn":"足球场"}},{"en":"how high or low a sound is, especially a musical note","cn":"（尤指乐音的）音高","g":"[singular, uncountable]","sc":"of sound","ex":{"en":"A basic sense of rhythm and pitch is essential in a music teacher.","cn":"基本的韵律感和音高感是音乐教师的必备素质。"}},{"en":"the degree or strength of a feeling or activity; the highest point of something","cn":"（感情或活动的）程度，力度；（事物的）最高点","g":"[singular, uncountable]","sc":"degree/strength","ex":{"en":"a frenetic pitch of activity","cn":"活动的狂热极点"}},{"en":"talk or arguments used by a person trying to sell something or persuade people to do something","cn":"推销的话；说教；宣传论点","g":"[countable, usually singular]","sc":"to sell something","ex":{"en":"an aggressive sales pitch","cn":"强有力的推销行话"}},{"en":"an act of throwing the ball; the way in which it is thrown","cn":"投球；投球方法","g":"[countable]","lab":"especially British English","sc":"in baseball"},{"en":"a black sticky substance made from oil or coal, used on roofs or the wooden boards of a ship to stop water from coming through","cn":"沥青；柏油","g":"[uncountable]","sc":"black substance"},{"en":"a place in a street or market where somebody sells things, or where somebody performs in order to entertain people outdoors","cn":"（街头售货或艺人演出的）摊点，场子","g":"[countable]","lab":"British English","sc":"in street/market"},{"en":"a place in a campsite where you can put up one tent or park one caravan, etc.","cn":"（露营地中的）营位","lab":"British English","sc":"camping","ex":{"en":"Pitches to rent from only £15 per night.","cn":"营位租金每晚仅 15 英镑起。"}},{"en":"the movement of a ship up and down in the water or of an aircraft in the air","cn":"（船在水上的）上下颠簸，纵摇；（飞机在空中的）俯仰","g":"[uncountable]","lab":"specialist","sc":"of ship/aircraft"},{"en":"the degree to which a roof slopes","cn":"倾斜度","g":"[singular, uncountable]","lab":"specialist","sc":"of roof","ex":{"en":"The pitch of the roof is 45 degrees.","cn":"屋顶的坡度为45度。"}},{"en":"to throw somebody/something with force","cn":"用力扔；投；抛","g":"[transitive]","lab":"figurative","sc":"throw","ex":{"en":"The explosion pitched her violently into the air.","cn":"爆炸把她猛烈地抛向空中。"},"pos":"verb"},{"en":"to throw the ball to the person who is batting","cn":"将（球）投给击球员；投球；当投手","g":"[intransitive, transitive]","sc":"in sports","ex":{"en":"He pitched against UCLA last week.","cn":"他上周担任投手，对阵加州大学洛杉矶分校。"},"pos":"verb"},{"en":"to hit the ground; to make the ball hit the ground","cn":"触地；（使球）定点落地","g":"[intransitive, transitive]","sc":"in sports","ex":{"en":"The ball pitched a yard short of the hole.","cn":"球在离洞一码处落地。"},"pos":"verb"},{"en":"to hit the ball in a high curve","cn":"劈高球；击高球","g":"[transitive, intransitive]","sc":"in sports","pos":"verb"},{"en":"to fall heavily in a particular direction","cn":"重跌；踉跄倒下","g":"[intransitive]","sc":"fall","ex":{"en":"With a cry she pitched forward.","cn":"她大叫一声向前跌倒了。"},"pos":"verb"},{"en":"to move up and down on the water or in the air","cn":"纵摇；颠簸；上下飘荡","g":"[intransitive]","sc":"of ship/aircraft","ex":{"en":"The sea was rough and the ship pitched and rolled all night.","cn":"大海波涛汹涌，船整夜颠簸摇晃。"},"pos":"verb"},{"en":"to set something at a particular level","cn":"确定标准","g":"[transitive]","sc":"set level","ex":{"en":"They have pitched their prices too high.","cn":"他们把价格定得太高了。"},"pos":"verb"},{"en":"to aim or direct a product or service at a particular group of people","cn":"（使产品或服务）针对，面向；确定销售对象（或目标市场）","g":"[transitive]","sc":"try to sell","ex":{"en":"The new software is being pitched at banks.","cn":"这种新软件以银行为目标市场。"},"pos":"verb"},{"en":"to try to persuade somebody to buy something, to give you something or to make a business deal with you","cn":"推销；争取支持（或生意等）","g":"[transitive, intransitive]","sc":"try to sell","ex":{"en":"Representatives went to Japan to pitch the company's newest products.","cn":"销售代表前往日本推销公司的最新产品。"},"pos":"verb"},{"en":"to produce a sound or piece of music at a particular level","cn":"定音高","g":"[transitive]","sc":"sound/music","ex":{"en":"You pitched that note a little flat.","cn":"你把那个音符定得有点低了。"},"pos":"verb"},{"en":"to set up a tent or a camp for a short time","cn":"搭（帐篷）；扎（营）","g":"[transitive]","sc":"tent","ex":{"en":"We could pitch our tent in that field.","cn":"我们可以临时把帐篷搭在那块地上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（足球、板球、曲棍球等运动的）球场","en":"A pitch is an area of ground that is marked out and used for playing a game such as football, cricket, or hockey.","ex":{"en":"There was a swimming-pool, cricket pitches, playing fields","cn":"有一个游泳池、几个板球场和运动场。"}},{"pos":"VERB 动词","cn":"（通常指仔细瞄准后用力）投，掷，扔，抛","en":"If you pitch something somewhere, you throw it with quite a lot of force, usually aiming it carefully.","ex":{"en":"Simon pitched the empty bottle into the lake.","cn":"西蒙把空瓶子扔到湖里。"}},{"pos":"VERB 动词","cn":"（猛地）向前跌倒","en":"To pitch somewhere means to fall forwards suddenly and with a lot of force.","ex":{"en":"The movement took him by surprise, and he pitched forward","cn":"这一动使他冷不防地向前摔倒。"}},{"pos":"VERB 动词","cn":"迫使…进入（新的境地）","en":"If someone is pitched into a new situation, they are suddenly forced into it.","ex":{"en":"They were being pitched into a new adventure","cn":"他们正被抛入一场新的冒险。"}},{"pos":"VERB 动词","cn":"（棒球或跑柱式棒球运动中）把（球）投给击球员","en":"In the game of baseball or rounders, when you pitch the ball, you throw it to the batter for them to hit it.","ex":{"en":"We passed long, hot afternoons pitching a baseball.","cn":"我们通过投棒球玩打发了一个个漫长、炎热的下午。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"音高","en":"The pitch of a sound is how high or low it is.","ex":{"en":"He raised his voice to an even higher pitch.","cn":"他把音调抬得更高了。"}},{"pos":"VERB 动词","cn":"为…定音高；为…定调","en":"If a sound is pitched at a particular level, it is produced at the level indicated.","ex":{"en":"His cry is pitched at a level that makes it impossible to ignore","cn":"他的哭喊声之大让人没法不理睬。"}},{"pos":"VERB 动词","cn":"把…定（在特定的水平、难易程度等上）","en":"If something is pitched at a particular level or degree of difficulty, it is set at that level.","ex":{"en":"I think the material is pitched at too high a level for our purposes","cn":"我想相对于我们的意图来说，内容定得过难了。"}},{"pos":"N-SING 单数名词","cn":"程度；强度；极点；顶点","en":"If something such as a feeling or a situation rises to a high pitch, it rises to a high level.","ex":{"en":"I feel very sorry for the competitors who have all worked themselves up to a very high pitch for this first day","cn":"我为第一天就已耗费相当大体力的参赛者感到非常惋惜。"}},{"pos":"VERB 动词","cn":"搭（帐篷）；扎（营）","en":"If you pitch your tent, or pitch camp, you put up your tent in a place where you are going to stay.","ex":{"en":"He had pitched his tent in the yard","cn":"他在院子里搭起了帐篷。"}},{"pos":"VERB 动词","cn":"（船只在海浪中）上下颠簸，纵摇","en":"If a boat pitches, it moves violently up and down with the movement of the waves when the sea is rough.","ex":{"en":"The ship is pitching and rolling in what looks like about fifteen foot seas.","cn":"这只船在看起来约有15英尺高的海浪中上下左右颠簸。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"沥青；柏油","en":"Pitch is a black substance that is sticky when it is hot and very hard when it is dry. Pitch is used on the bottoms of boats and on the roofs of houses to prevent water getting in.","ex":{"en":"The timbers of similar houses were painted with pitch.","cn":"类似房屋所用的栋木刷了沥青。"}},{"pos":"PHRASE 短语","cn":"为…作宣传；替…说好话","en":"If someone makes a pitch for something, they try to persuade people to do or buy it.","ex":{"en":"The President speaks in New York today, making another pitch for his economic program","cn":"总统今天在纽约发表讲话，再一次为他的经济计划作宣传。"}},{"pos":"","cn":"","en":"相关词组：pitch for pitch in"}]},"examples":[{"en":"We were pitching against a much larger company for the contract.","cn":"我们在与一家比我们大得多的公司竞争这项合同。"},{"en":"A basic sense of rhythm and pitch is essential in a music teacher.","cn":"基本的韵律感和音高感是音乐教师的必备素质。"}]},"pitiful":{"media":{"uk":"media/uk/pitiful__gb_1.mp3","us":"media/us/pitiful__us_1.mp3"},"oxford":{"phon":"ˈpɪtɪfl","pos":"adjective","senses":[{"en":"deserving pity or causing you to feel pity","cn":"可怜的；令人怜悯的；令人同情的","ex":{"en":"The horse was a pitiful sight (= because it was very thin or sick).","cn":"这匹马看上去可怜兮兮的。"}},{"en":"not deserving respect","cn":"卑微的；卑鄙的","ex":{"en":"a pitiful effort/excuse/performance","cn":"不值一提的努力／借口／表现"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人怜悯的；使人同情的；可怜的","en":"Someone or something that is pitiful is so sad, weak, or small that you feel pity for them.","ex":{"en":"He sounded both pitiful and eager to get what he wanted","cn":"他听起来既可怜兮兮的，又对想要的东西充满渴望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"匮乏的；极度欠缺的","en":"If you describe something as pitiful, you mean that it is completely inadequate.","ex":{"en":"The choice is pitiful and the quality of some of the products is very low","cn":"选择余地极小，而且其中一些产品的质量很差。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可鄙的；不值得考虑的","en":"If you describe something as pitiful, you mean that it does not deserve respect or consideration.","ex":{"en":"This argument seems to show a pitiful lack of confidence in the capabilities of our juries.","cn":"这一论点似乎表现出对我们陪审团能力的极度不信任，而这种不信任是可悲的。"}}]},"examples":[{"en":"The horse was a pitiful sight (= because it was very thin or sick).","cn":"这匹马看上去可怜兮兮的。"},{"en":"The dog was whining pitifully.","cn":"那条狗可怜巴巴地哀叫着。"}]},"pity":{"media":{"uk":"media/uk/pity__gb_1.mp3","us":"media/us/pity__us_1.mp3"},"oxford":{"phon":"ˈpɪti","pos":"noun","senses":[{"en":"used to show that you are disappointed about something","cn":"（表示失望）遗憾，可惜","g":"[singular]","ex":{"en":"It's a pity that you can't stay longer.","cn":"你不能再多停留些时间，真是遗憾。"}},{"en":"a sad feeling caused by the pain and troubles of others","cn":"同情；怜悯","g":"[uncountable]","lab":"formal","ex":{"en":"I took pity on her and lent her the money.","cn":"我同情她，就把钱借给了她。"}},{"en":"to feel sorry for somebody because of their situation; to feel pity for somebody","cn":"同情；怜悯；可怜","ex":{"en":"He pitied people who were stuck in dead-end jobs.","cn":"他很同情那些工作上毫无前途的人。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同情；怜悯；可怜","en":"If you feel pity for someone, you feel very sorry for them.","ex":{"en":"He felt a sudden tender pity for her","cn":"他突然涌起一股对她的温柔怜悯之情。"}},{"pos":"VERB 动词","cn":"同情；怜悯；可怜","en":"If you pity someone, you feel very sorry for them.","ex":{"en":"I don't know whether to hate or pity him.","cn":"我不知道该恨他，还是该同情他。"}},{"pos":"N-SING 单数名词","cn":"可惜的事；遗憾的事","en":"If you say that it is a pity that something is the case, you mean that you feel disappointment or regret about it.","ex":{"en":"It is a great pity that all pupils in the city cannot have the same chances","cn":"非常遗憾的是，在这个城市里，并非所有的学生都能获得同样的机会。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"仁慈；慈悲","en":"If someone shows pity, they do not harm or punish someone they have power over.","ex":{"en":"One should avoid showing too much pity","cn":"一个人应该避免显得太过仁慈。"}},{"pos":"PHR with cl","cn":"不幸的是；遗憾的是","en":"If you add more's the pity to a comment, you are expressing your disappointment or regret about something.","ex":{"en":"But my world isn't your world, more's the pity.","cn":"可惜的是，我们是两个世界的人。"}},{"pos":"PHRASE 短语","cn":"（尤在恼怒或不快时用于强调）行行好，发发慈悲吧","en":"You can say for pity's sake to add emphasis to what you are saying, especially when you are annoyed or upset.","ex":{"en":"'Run, Katherine. For pity's sake run!' he screamed.","cn":"“跑，凯瑟琳，快跑！”他尖叫道。"}},{"pos":"PHRASE 短语","cn":"对…表示同情；对…表示怜悯","en":"If you take pity on someone, you feel sorry for them and help them.","ex":{"en":"No woman had ever felt the need to take pity on him before.","cn":"以前从没有女性觉得他需要同情。"}},{"pos":"PHRASE 短语","cn":"（用于强调）可惜的是，遗憾的是","en":"If you say the pity is that, or the pity of it is that, before a comment, you are emphasizing your disappointment or regret about something.","ex":{"en":"The pity is that it was all completely unnecessary","cn":"遗憾的是这完全没有必要。"}}]},"examples":[{"en":"‘Was the bicycle insured?’ ‘No, more's the pity!’ “","cn":"自行车上保险没有？” “没有。真倒霉！”"},{"en":"‘I've lost it!’ ‘Oh, what a pity. ’ “","cn":"我把东西弄丢了！” “哎呀，真可惜。”"}]},"pizza":{"media":{"uk":"media/uk/pizza__gb_1.mp3","us":"media/us/pizza__us_1.mp3","img":["media/ldoce/img/pizza.jpg"]},"oxford":{"phon":"ˈpiːtsə","pos":"noun","senses":[{"en":"an Italian dish consisting of a flat round bread base with cheese, tomatoes, vegetables, meat, etc. on top","cn":"比萨饼；意大利肉饼","ex":{"en":"a ham and mushroom pizza","cn":"火腿蘑菇比萨饼"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"意大利薄饼；比萨饼","en":"A pizza is a flat, round piece of dough covered with tomatoes, cheese, and other savoury food, and then baked in an oven.","ex":{"en":"...the last piece of pizza","cn":"最后一块比萨饼"}}]},"examples":[{"en":"Is there any pizza left?","cn":"还有比萨饼吗？"},{"en":"a ham and mushroom pizza","cn":"火腿蘑菇比萨饼"}]},"pitiless":{"media":{"uk":"media/uk/pitiless__gb_1.mp3","us":"media/us/pitiless__us_1.mp3"},"oxford":{"phon":"ˈpɪtiləs","pos":"adjective","senses":[{"en":"showing no pity; cruel","cn":"冷酷的；无情的","ex":{"en":"a pitiless killer/tyrant","cn":"残忍的凶手／暴君"}},{"en":"very cruel or severe, and never ending","cn":"严酷而无尽的","ex":{"en":"a scorching, pitiless sun","cn":"灼热的骄阳"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无情的；无怜悯之心的","en":"Someone or something that is pitiless shows no pity or kindness.","ex":{"en":"He saw the pitiless eyes of his enemy","cn":"他看到了敌人冷酷的眼神。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）严酷的，恶劣的","en":"If you describe something such as the weather or the heat as pitiless, you mean that it is very extreme.","ex":{"en":"John Steinbeck used the dust and the pitiless skies as the backcloth to his novel.","cn":"约翰·斯坦贝克把尘土和烈日炙烤的天空用作小说的背景。"}}]},"examples":[{"en":"a pitiless killer/tyrant","cn":"残忍的凶手/暴君"},{"en":"a scorching, pitiless sun","cn":"灼热的骄阳"}]},"pits":{"oxford":{"phon":"pɪt","pos":"noun","senses":[{"en":"a large deep hole in the ground","cn":"深洞；深坑"},{"en":"( especially in compounds","cn":"尤用于构成复合词 ) a deep hole in the ground from which minerals are dug out 矿井"}]}},"pink":{"oxford":{"phon":"pɪŋk","pos":"adjective","senses":[{"en":"pale red in colour","cn":"粉红色的","ex":{"en":"pale pink roses","cn":"淡粉色的玫瑰"}},{"en":"connected with gay people","cn":"与同性恋者有关的","g":"[only before noun]","lab":"British English","ex":{"en":"the pink pound (= money spent by gays and lesbians as an influence in the economy)","cn":"同性恋群体消费力"}},{"en":"having or showing slightly left-wing political views","cn":"政治观点偏左的；略呈左倾的","lab":"informal, disapproving, politics，，，，","ex":{"en":"pale pink politics","cn":"带左倾色彩的政治。"}},{"en":"the colour that is produced when you mix red and white together","cn":"粉红色","g":"[uncountable, countable]","ex":{"en":"She was dressed in pink.","cn":"她穿着粉红色的衣服。"},"pos":"noun"},{"en":"a garden plant with pink, red or white flowers that have a sweet smell","cn":"香石竹；石竹","g":"[countable]","pos":"noun"},{"en":"to make knocking sounds because the fuel is not burning correctly","cn":"发爆声；敲缸","pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"粉红色；淡红色","en":"Pink is the colour between red and white.","ex":{"en":"...pink lipstick.","cn":"粉红色的口红"}},{"pos":"COLOUR 颜色词","cn":"（因窘迫、愤怒或剧烈活动而）脸色发红","en":"If you go pink, your face turns a slightly redder colour than usual because you are embarrassed or angry, or because you are doing something energetic.","ex":{"en":"She went pink again as she remembered her mistake.","cn":"想起自己的错误，她又脸红了。"}},{"pos":"ADJ 形容词","cn":"与同性恋者有关的","en":"Pink is used to refer to things relating to or connected with homosexuals.","ex":{"en":"Businesses are now more aware of the importance of the 'pink pound'.","cn":"现在商家更加意识到同性恋族群消费力、即所谓“粉红英镑”的重要性。"}},{"pos":"N-COUNT 可数名词","cn":"石竹","en":"Pinks are small plants that people grow in their gardens. They have sweet-smelling pink, white, or red flowers."},{"pos":"PHRASE 短语","cn":"非常健康；满面红光；容光焕发","en":"If you are in the pink, you are fit, healthy, and happy.","ex":{"en":"A glass of red wine keeps you in the pink.","cn":"一杯红酒有益健康。"}},{"pos":"","cn":"","en":"to be tickled pink→see: ;"}]},"media":{"uk":"media/uk/pink__gb_1.mp3","us":"media/us/pink__us_1.mp3"},"examples":[{"en":"She was dressed in pink.","cn":"她穿着粉红色的衣服。"},{"en":"The bedroom was decorated in pale pinks.","cn":"卧室涂成了淡粉红色。"}]},"pious":{"oxford":{"phon":"ˈpaɪəs","pos":"adjective","senses":[{"en":"having or showing a deep respect for God and religion","cn":"虔诚的；虔敬的","ex":{"en":"pious acts","cn":"虔诚之举"}},{"en":"pretending to be religious, moral or good in order to impress other people","cn":"道貌岸然的；伪善的；假正经的","lab":"disapproving","ex":{"en":"pious sentiments","cn":"虚情假意"}},{"en":"something that you want to happen but is unlikely to be achieved","cn":"可望而不可即的；难以实现的","ex":{"en":"Such reforms seem likely to remain little more than pious hopes.","cn":"这类改革可能只是画饼充饥而已。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虔诚的；笃信宗教的","en":"Someone who is pious is very religious and moral.","ex":{"en":"He was brought up by pious female relatives.","cn":"他是由虔诚的女性亲属带大的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言辞）不可能实现的","en":"If you describe someone's words as pious, you think that their words are full of good intentions but do not lead to anything useful being done.","ex":{"en":"What we need is not manifestos of pious intentions, but real action.","cn":"我们需要的不是善意但难以实现的宣言，而是实际行动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"假装虔诚的；伪善的","en":"If you describe someone as pious, you disapprove of the fact that they pretend to be very religious without being sincere.","ex":{"en":"His attitude is compassionate without being pious.","cn":"他的态度是真心实意的同情。"}}]},"media":{"uk":"media/uk/pious__gb_1.mp3","us":"media/us/pious__us_1.mp3"},"examples":[{"en":"Such reforms seem likely to remain little more than pious hopes.","cn":"这类改革可能只是画饼充饥而已。"},{"en":"pious acts","cn":"虔诚之举"}]},"pillar":{"media":{"uk":"media/uk/pillar__gb_1.mp3","us":"media/us/pillar__us_1.mp3","img":["media/ldoce/img/column.jpg"]},"oxford":{"phon":"ˈpɪlə(r)","pos":"noun","senses":[{"en":"a large round stone, metal or wooden post that is used to support a bridge, the roof of a building, etc., especially when it is part of an attractive design","cn":"（尤指兼作装饰的）柱子，桥墩","ex":{"en":"Two white marble pillars stood on either side of the entrance.","cn":"入口两侧立着两根白色大理石柱子。"}},{"en":"a large round stone, metal or wooden post that is built to remind people of a famous person or event","cn":"纪念柱"},{"en":"a mass of something that is like a pillar in shape","cn":"柱状物","ex":{"en":"a pillar of smoke/rock","cn":"烟柱；石柱"}},{"en":"a strong supporter of something; an important member of something","cn":"台柱子；主心骨；中流砥柱","ex":{"en":"He was a pillar of the Church.","cn":"他是教会的骨干分子。"}},{"en":"a person who has a lot of a particular quality","cn":"富有某种素质的人；某种素质的化身","ex":{"en":"She is a pillar of strength in a crisis.","cn":"她在危难中表现非常坚强。"}},{"en":"a basic part or feature of a system, organization, belief, etc.","cn":"（组织、制度、信仰等的）核心，基础，支柱","ex":{"en":"the central pillar of this theory","cn":"这一理论的核心支柱"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"柱；柱子","en":"A pillar is a tall solid structure, which is usually used to support part of a building.","ex":{"en":"...the pillars supporting the roof.","cn":"支撑屋顶的柱子"}},{"pos":"N-COUNT 可数名词","cn":"（制度、协议等的）支柱，核心","en":"If something is the pillar of a system or agreement, it is the most important part of it or what makes it strong and successful.","ex":{"en":"The pillar of her economic policy was keeping tight control over money supply.","cn":"她经济政策的核心是严格控制货币的供应。"}},{"pos":"N-COUNT 可数名词","cn":"中坚；栋梁；台柱","en":"If you describe someone as a pillar of society or as a pillar of the community, you approve of them because they play an important and active part in society or in the community.","ex":{"en":"My father had been a pillar of the community.","cn":"我父亲一直是社区的顶梁柱。"}}]},"examples":[{"en":"She is a pillar of strength in a crisis.","cn":"她在危难中表现非常坚强。"},{"en":"the central pillar of this theory","cn":"这一理论的核心支柱"}]},"pitcher":{"media":{"img":["media/pic/jug_pitcher.jpg","media/thumb/pitcher.jpg"],"uk":"media/uk/pitcher__gb_1.mp3","us":"media/us/pitcher__us_1.mp3"},"oxford":{"phon":"ˈpɪtʃə(r)","pos":"noun","senses":[{"en":"a container with a handle and a lip, for holding and pouring liquids","cn":"（有柄有嘴的）壶，罐","lab":"North American English","ex":{"en":"a pitcher of water","cn":"一罐水"}},{"en":"a large clay container with a small opening and one or two handles, used, especially in the past, for holding liquids","cn":"（尤指旧时的）带柄的陶罐","lab":"British English"},{"en":"the player who throws the ball to the batter","cn":"投手","ex":{"en":"Left-handed hitters usually prefer facing right-handed pitchers.","cn":"左手击球员通常喜欢面对右投手。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（有柄有嘴的）罐，壶","en":"A pitcher is a jug.","ex":{"en":"...a pitcher of iced water.","cn":"一罐冰水"}},{"pos":"N-COUNT 可数名词","cn":"（通常指筒状细颈双耳的）陶罐，陶壶","en":"A pitcher is a large container made of clay. Pitchers are usually round in shape and have a narrow neck and two handles shaped like ears."},{"pos":"N-COUNT 可数名词","cn":"（棒球运动中的）投手","en":"In baseball, the pitcher is the person who throws the ball to the batter, who tries to hit it.","ex":{"en":"Over the next five years, he became one of the greatest pitchers in baseball.","cn":"在接下来的5年时间里，他成为了最了不起的棒球投手之一。"}}]},"examples":[{"en":"a pitcher of water","cn":"一罐水"}]},"pigeon":{"media":{"uk":"media/uk/pigeon__gb_1.mp3","us":"media/us/pigeon__us_1.mp3"},"oxford":{"phon":"ˈpɪdʒɪn","pos":"noun","senses":[{"en":"a fat grey and white bird with short legs. Pigeons are common in cities and also live in woods and fields where people shoot them for sport or food.","cn":"鸽子","ex":{"en":"the sound of pigeons cooing","cn":"鸽子咕咕的叫声"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸽子","en":"A pigeon is a bird, usually grey in colour, which has a fat body. Pigeons often live in towns. →see: ;"}]},"examples":[{"en":"the sound of pigeons cooing","cn":"鸽子咕咕的叫声"}]},"pi":{"oxford":{"phon":"paɪ","pos":"noun","senses":[{"en":"the symbol π used to show the ratio of the circumference of (= distance around) a circle to its diameter (= distance across), that is 3.14159…","cn":"圆周率","lab":"geometry"},{"en":"the 16th letter of the Greek alphabet (Π, π)","cn":"希腊字母表的第 16 个字母"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"圆周率（通常用希腊字母�表示，近似值为3.142）","en":"Pi is a number, approximately 3.142, which is equal to the distance round a circle divided by its width. It is usually represented by the Greek letter �."}]},"media":{"uk":"media/uk/pi__gb_1.mp3","us":"media/us/pi__us_1.mp3"}},"pigeons":{"oxford":{"phon":"ˈpɪdʒɪn","pos":"noun","senses":[{"en":"a fat grey and white bird with short legs. Pigeons are common in cities and also live in woods and fields where people shoot them for sport or food.","cn":"鸽子"},{"en":"( old-fashioned ) ( BrE ) to be sb's responsibility or business","cn":"是某人的职责（或事情）"}]},"media":{"uk":"media/uk/pigeon__gb_1.mp3","us":"media/us/pigeon__us_1.mp3"}},"pier":{"media":{"uk":"media/uk/pier__gb_1.mp3","us":"media/us/pier__us_1.mp3","img":["media/ldoce/img/pier.jpg"]},"oxford":{"phon":"pɪə(r)","pos":"noun","senses":[{"en":"a long structure built in the sea and joined to the land at one end, often with places of entertainment on it","cn":"（常设有娱乐场所的）突堤","ex":{"en":"After lunch, the family went for a walk along the pier.","cn":"午饭后，一家人沿着码头散步。"}},{"en":"a long low structure built in a lake, river or the sea and joined to the land at one end, used by boats to allow passengers to get on and off","cn":"（突入湖、河、海中的）码头；突码头","ex":{"en":"The river bus leaves from Pier 4.","cn":"河上巴士从 4 号码头出发。"}},{"en":"a large strong piece of wood, metal or stone that is used to support a roof, wall, bridge, etc.","cn":"墙墩；桥墩","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指伸向大海的）凸式码头，突码头，突堤","en":"A pier is a platform sticking out into water, usually the sea, which people walk along or use when getting onto or off boats.","ex":{"en":"...Brighton Pier.","cn":"布赖顿码头"}}]},"examples":[{"en":"a yacht moored at a pier","cn":"停在码头的一艘游艇"},{"en":"strolling along Brighton Pier","cn":"在布赖顿码头散步"}]},"piety":{"media":{"uk":"media/uk/piety__gb_1.mp3","us":"media/us/piety__us_1.mp3"},"oxford":{"phon":"ˈpaɪəti","pos":"noun","senses":[{"en":"the state of having or showing a deep respect for somebody/something, especially for God and religion; the state of being pious","cn":"虔诚"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"虔诚；虔敬","en":"Piety is strong religious belief, or behaviour that is religious or morally correct."}]},"examples":[{"en":"an act of Christian piety","cn":"表达基督徒虔诚的行为"}]},"piglet":{"oxford":{"phon":"ˈpɪɡlət","pos":"noun","senses":[{"en":"a young pig","cn":"猪仔；小猪"},{"en":"a character in A A Milne's children's stories about Winnie-the-Pooh. Piglet, a cheerful young pig, is one of Pooh's friends.","cn":"猪仔；小猪","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小猪；乳猪","en":"A piglet is a young pig."}]},"media":{"uk":"media/uk/piglet__gb_1.mp3","us":"media/us/piglet__us_1.mp3"}},"pilot":{"media":{"uk":"media/uk/pilot__gb_1.mp3","us":"media/us/pilot__us_1.mp3"},"oxford":{"phon":"ˈpaɪlət","pos":"noun","senses":[{"en":"a person who operates the controls of an aircraft, especially as a job","cn":"飞行员；（航空器）驾驶员","ex":{"en":"an airline pilot","cn":"民航飞行员"}},{"en":"a person with special knowledge of a difficult area of water, for example, the entrance to a harbour, whose job is to guide ships through it","cn":"领航员；引水员；领港员"},{"en":"a single television programme that is made in order to find out whether people will like it and want to watch further programmes","cn":"（电视的）试播节目"},{"en":"a small flame that burns all the time, for example on a gas boiler, and lights a larger flame when the gas is turned on","cn":"引火火种；长明火"},{"en":"to fly an aircraft or guide a ship; to act as a pilot","cn":"驾驶（航空器）；领航（船只）","ex":{"en":"The plane was piloted by the instructor.","cn":"飞机由教练员驾驶。"},"pos":"verb"},{"en":"to guide somebody/something somewhere, especially through a complicated place or system","cn":"引导；使通过（尤指复杂的地方或系统）","ex":{"en":"She piloted a bill on the rights of part-time workers through parliament.","cn":"她几经周折终于使兼职人员权利法案在议会中得以通过。"},"pos":"verb"},{"en":"to test a new product, idea, etc. with a few people or in a small area before it is introduced everywhere","cn":"试点；试行","ex":{"en":"Several centres have been asked to pilot the new qualification.","cn":"一些中心已被要求试点新的资格。"},"pos":"verb"},{"en":"done on a small scale in order to see if something is successful enough to do on a large scale","cn":"试验性的；试点的","ex":{"en":"a pilot project/study/survey","cn":"试验性项目／研究／调查"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（飞机）驾驶员;飞行员","en":"A pilot is a person who is trained to fly an aircraft.","ex":{"en":"He spent seventeen years as an airline pilot.","cn":"他当了17年的航空公司飞行员。"}},{"pos":"N-COUNT 可数名词","cn":"（船舶的）引航员,领航员","en":"A pilot is a person who steers a ship through a difficult stretch of water, for example the entrance to a harbour."},{"pos":"VERB 动词","cn":"驾驶（飞机等）；为（船舶）引航","en":"If someone pilots an aircraft or ship, they act as its pilot.","ex":{"en":"He piloted his own plane part of the way to Washington.","cn":"乘私人飞机去华盛顿的路上，有一段行程是他自己驾驶的。"}},{"pos":"N-COUNT 可数名词","cn":"试验性的方案；试点性的项目","en":"A pilot scheme or a pilot project is one which is used to test an idea before deciding whether to introduce it on a larger scale.","ex":{"en":"The service is being expanded following the success of a pilot scheme.","cn":"在试验性方案获得成功后，这项服务正在推广中。"}},{"pos":"VERB 动词","cn":"试验；试行","en":"If a government or organization pilots a programme or a scheme, they test it, before deciding whether to introduce it on a larger scale.","ex":{"en":"The trust is looking for 50 schools to pilot a programme aimed at teenage pupils preparing for work.","cn":"该信托基金机构正在寻找50所学校，以试行一个旨在帮助青少年学生做就业准备的项目。"}},{"pos":"VERB 动词","cn":"使（新的法律或议案）顺利通过","en":"If a government minister pilots a new law or bill through parliament, he or she makes sure that it is introduced successfully.","ex":{"en":"We are now piloting through Parliament a new strategy to tackle youth crime.","cn":"我们正促使议会顺利通过解决青少年犯罪问题的一项新策略。"}},{"pos":"N-COUNT 可数名词","cn":"（电视的）试播节目，试播集","en":"A pilot or a pilot episode is a single television programme that is shown in order to find out whether a particular series of programmes is likely to be popular.","ex":{"en":"A pilot episode of Nothing's Impossible has already been filmed.","cn":"《一切皆有可能》的试播集已拍摄出来了。"}},{"pos":"N-COUNT 可数名词","cn":"（煤气灶具、锅炉等用于引火的）常燃小火","en":"A pilot is the pilot light on a gas cooker or stove, boiler, or fire."}]},"examples":[{"en":"She piloted a bill on the rights of part-time workers through parliament.","cn":"她几经周折终于使兼职劳工权利法案在议会中得以通过。"},{"en":"The accident was caused by pilot error.","cn":"这场事故是飞行员的失误造成的。"}]},"piece":{"media":{"uk":"media/uk/piece__gb_1.mp3","us":"media/us/piece__us_1.mp3","img":["media/ldoce/img/piece_cheese.jpg"]},"oxford":{"phon":"piːs","pos":"noun","senses":[{"en":"an amount of something that has been cut or separated from the rest of it; a standard amount of something","cn":"片；块；段；截；标准的量","g":"[countable]","lab":"British English","sc":"separate amount","ex":{"en":"She wrote something on a small piece of paper.","cn":"她在一小片纸上写了点什么。"}},{"en":"one of the bits or parts that something breaks into","cn":"碎片；碎块","g":"[countable, usually plural]","sc":"part","ex":{"en":"There were tiny pieces of glass all over the road.","cn":"道路上满是碎玻璃渣。"}},{"en":"one of the parts that something is made of","cn":"零件；部件","g":"[countable]","sc":"part","ex":{"en":"He took the clock to pieces.","cn":"他把钟拆散了。"}},{"en":"a single item of a particular type, especially one that forms part of a set","cn":"（尤指一套中的）一件","g":"[countable]","sc":"single item","ex":{"en":"a piece of equipment/furniture","cn":"一件设备／家具"}},{"en":"used with many uncountable nouns to describe a single example or an amount of something","cn":"条；项；点","g":"[countable]","sc":"single item","ex":{"en":"a piece of information/evidence/advice/news/legislation","cn":"一条信息；一个证据／建议；一则新闻；一项立法"}},{"en":"a single item of writing, art, music, etc. that somebody has produced or created; a short item of writing from a longer work","cn":"（文章、艺术品、音乐作品等的）一篇，一件，一首，一段","g":"[countable]","lab":"formal","sc":"single item","ex":{"en":"a piece of music/art","cn":"一首乐曲；一件艺术品"}},{"en":"an article in a newspaper or magazine or a broadcast on television or radio","cn":"（新闻传媒的）文章，报道","g":"[countable]","sc":"news article","ex":{"en":"The Washington Post ran a series of opinion pieces criticizing the policy.","cn":"《华盛顿邮报》发表了一系列评论文章批评该政策。"}},{"en":"a coin of the value mentioned","cn":"（某价值的）硬币","g":"[countable]","sc":"coin","ex":{"en":"a 50p piece","cn":"一枚 50 便士的硬币"}},{"en":"one of the small figures or objects that you move around in games such as chess","cn":"棋子","g":"[countable]","sc":"in chess, etc."},{"en":"a part or share of something","cn":"部分；份额","g":"[singular]","lab":"especially North American English","sc":"share of something","ex":{"en":"companies seeking a piece of the market","cn":"争取市场份额的公司"}},{"en":"a gun","cn":"枪","g":"[countable]","lab":"North American English, slang，，","sc":"gun"},{"en":"a short distance","cn":"短距离；一小段距离","g":"[singular]","lab":"North American English, old-fashioned, informal，，，，","sc":"distance","ex":{"en":"She lives down the road a piece from here.","cn":"她住在路那头离这里不远的地方。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（断下、撕下或切下的）块，片，段，截","en":"A piece of something is an amount of it that has been broken off, torn off, or cut off.","ex":{"en":"...a piece of cake.","cn":"一块蛋糕"}},{"pos":"N-COUNT 可数名词","cn":"（尤指可拆卸的）部件，部分","en":"A piece of an object is one of the individual parts or sections which it is made of, especially a part that can be removed.","ex":{"en":"...assembling objects out of standard pieces","cn":"用标准部件组装物品"}},{"pos":"N-COUNT 可数名词","cn":"（土地的）一块，一片","en":"A piece of land is an area of land.","ex":{"en":"People struggle to get the best piece of land.","cn":"人们竞相争夺最好的土地。"}},{"pos":"N-COUNT 可数名词","cn":"（与不可数名词连用）桩，项，条，件","en":"You can use piece of with many uncount nouns to refer to an individual thing of a particular kind. For example, you can refer to some advice as a piece of advice.","ex":{"en":"When I produced this piece of work, my lecturers were very critical","cn":"当我拿出这件作品时，我的讲师们提出了诸多批评意见。"}},{"pos":"N-COUNT 可数名词","cn":"（报纸或杂志上的一篇）文章；（一首或一部）音乐作品；（一段）广播节目；（一出）戏剧","en":"You can refer to an article in a newspaper or magazine, some music written by someone, a broadcast, or a play as a piece .","ex":{"en":"I disagree with Andrew Russell over his piece on British Rail.","cn":"我不同意安德鲁·拉塞尔那篇关于英国铁路公司的文章。"}},{"pos":"N-COUNT 可数名词","cn":"（一件）艺术品","en":"You can refer to a work of art as a piece .","ex":{"en":"Each piece is unique, an exquisite painting of a real person, done on ivory","cn":"每一件艺术品都是绘在象牙上的精美绝伦的真人肖像，都是独一无二的。"}},{"pos":"N-COUNT 可数名词","cn":"硬币","en":"You can refer to specific coins as pieces. For example, a 10p piece is a coin that is worth 10p."},{"pos":"N-COUNT 可数名词","cn":"棋子","en":"The pieces which you use when you play a board game such as chess are the specially made objects which you move around on the board."},{"pos":"QUANT 数量词","cn":"（某物的）一部分，一份","en":"A piece of something is part of it or a share of it.","ex":{"en":"They got a small piece of the net profits and a screen credit.","cn":"他们得到了一小部分纯利润以及电影演职人员字幕中的署名权。"}},{"pos":"PHRASE 短语","cn":"向…表明不满；对…直言","en":"If you give someone a piece of your mind, you tell them very clearly that you think they have behaved badly.","ex":{"en":"How very thoughtless. I'll give him a piece of my mind.","cn":"真是太没头脑了，我要告诉他我很生气。"}},{"pos":"PHRASE 短语","cn":"（与…）一致","en":"If something with several different parts is all of a piece, each part is consistent with the others. If one thing is of a piece with another, it is consistent with it.","ex":{"en":"At its peak in the Thirties, Underground design and architecture was all of a piece","cn":"在30年代的顶峰时期，地铁的设计和建筑风格都一模一样。"}},{"pos":"PHRASE 短语","cn":"安然无恙的；完好无损的","en":"If someone or something is still in one piece after a dangerous journey or experience, they are safe and not damaged or hurt.","ex":{"en":"...providing that my brother gets back alive and in one piece from his mission.","cn":"如果我哥哥执行任务能够平安归来"}},{"pos":"PHRASE 短语","cn":"说自己想说的话；（毫不保留且不受打断地）发表意见","en":"If you say your piece, you say everything you want to say about a particular matter without being interrupted, although people may be wanting to express opposing views.","ex":{"en":"I'll answer your questions when I've said my piece.","cn":"说完我想说的，我会回答你的问题。"}},{"pos":"PHRASE 短语","cn":"成碎片地；散了架地；成组件地","en":"You use to pieces in expressions such as 'smash to pieces', and mainly in British English 'fall to pieces' or 'take something to pieces', when you are describing how something is broken or comes apart so that it is in separate pieces.","ex":{"en":"If the shell had hit the boat, it would have blown it to pieces","cn":"如果炮弹击中了小船，它早就被炸成碎片了。"}},{"pos":"PHRASE 短语","cn":"（难过或紧张得）崩溃，垮掉","en":"If you go to pieces, you are so upset or nervous that you lose control of yourself and cannot do what you should do.","ex":{"en":"She's a strong woman, but she nearly went to pieces when Arnie died.","cn":"她是个坚强的女性，但阿尼去世时，她几乎崩溃了。"}},{"pos":"PHRASE 短语","cn":"把…说得一钱不值；把…批得体无完肤","en":"If someone tears you to pieces ,pulls your work to pieces, or picks your work to pieces, they criticize you or your work very severely.","ex":{"en":"He made numerous errors of fact and was torn to pieces during the subsequent question time","cn":"他犯了数不清的事实错误，并在随后的答疑时间中被批得体无完肤。"}},{"pos":"PHRASE 短语","cn":"下流坯；坏东西；恶棍","en":"If you say that someone is a nasty piece of work, you mean that they are very unkind or unpleasant."},{"pos":"","cn":"","en":"a piece of the action→see: ; bits and pieces→see: ; a piece of cake→see: ; to pick up the pieces→see: ;"},{"pos":"","cn":"","en":"相关词组：piece together"}]},"examples":[{"en":"a piece of paper / wood / string / cake / fruit / meat / work / research / advice","cn":"一张纸；一块木头；一根绳子；一块蛋糕；一个水果；一块肉；一件工作；一项研究；一个忠告"},{"en":"Did you see her piece about the Internet in the paper today?","cn":"你看了今天报纸上她写的关于互联网的文章没有？"}]},"pipe":{"media":{"img":["media/pic/pipe_comp.jpg","media/thumb/pipe.jpg"],"uk":"media/uk/pipe__gb_1.mp3","us":"media/us/pipe__us_1.mp3"},"oxford":{"phon":"paɪp","pos":"noun","senses":[{"en":"a tube through which liquids and gases can flow","cn":"管子；管道","g":"[countable, uncountable]","lab":"British English","ex":{"en":"Both hot and cold water pipes should be properly insulated.","cn":"热水管和冷水管均应适当隔热。"}},{"en":"a narrow tube with a bowl at one end, used for smoking tobacco","cn":"烟斗；烟袋","g":"[countable]","ex":{"en":"to smoke a pipe","cn":"抽烟斗"}},{"en":"a musical instrument in the shape of a tube, played by blowing","cn":"管乐器","g":"[countable]"},{"en":"any of the tubes from which sound is produced in an organ","cn":"（管风琴的）音管","g":"[countable]"},{"en":"a musical instrument played especially in Scotland. The player blows air into a bag held under the arm and then slowly forces the air out through pipes to produce a noise.","cn":"风笛","g":"[plural]","lab":"North American English also"},{"en":"to send water, gas, oil, etc. through a pipe from one place to another","cn":"用管道输送","g":"[transitive]","ex":{"en":"to pipe oil across the desert","cn":"用管子把石油输送过沙漠"},"pos":"verb"},{"en":"to send sounds or signals through a wire or cable from one place to another","cn":"用线路系统传输（或传送）","g":"[transitive]","ex":{"en":"The speech was piped over a public address system.","cn":"讲话经广播系统传送出去。"},"pos":"verb"},{"en":"to play music on a pipe or the bagpipes, especially to welcome somebody who has arrived","cn":"用管乐器演奏（尤指迎宾曲）","g":"[transitive, intransitive]","ex":{"en":"Passengers were piped aboard ship at the start of the cruise.","cn":"游客在管乐迎宾曲中登船，开启游轮之旅。"},"pos":"verb"},{"en":"to speak or sing in a high voice or with a high sound","cn":"尖声地说（或唱）；尖声啼鸣","g":"[intransitive, transitive]","ex":{"en":"Outside a robin piped.","cn":"外面有一只知更鸟在啼鸣。"},"pos":"verb"},{"en":"to decorate food, especially a cake, with thin lines of icing, etc. by forcing it out of a special bag or tube","cn":"裱花（用裱花袋把糖霜等裱在糕点上）","g":"[transitive]","ex":{"en":"The cake had ‘Happy Birthday’ piped on it.","cn":"蛋糕上裱了“生日快乐”的字样。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指金属或塑料制的）管子，管道","en":"A pipe is a long, round, hollow object, usually made of metal or plastic, through which a liquid or gas can flow.","ex":{"en":"They had accidentally damaged a gas pipe while drilling","cn":"打钻时，他们不小心钻破了一根燃气管道。"}},{"pos":"N-COUNT 可数名词","cn":"烟斗；烟筒","en":"A pipe is an object which is used for smoking tobacco. You put the tobacco into the cup-shaped part at the end of the pipe, light it, and breathe in the smoke through a narrow tube."},{"pos":"N-COUNT 可数名词","cn":"管乐器","en":"A pipe is a simple musical instrument in the shape of a tube with holes in it. You play a pipe by blowing into it while covering and uncovering the holes with your fingers."},{"pos":"N-PLURAL 复数名词","cn":"pipes 同 bagpipes","en":"Pipes are the same as bagpipes ."},{"pos":"N-COUNT 可数名词","cn":"（管风琴的）音管， 风管","en":"An organ pipe is one of the long hollow tubes in which air vibrates and produces a musical note."},{"pos":"VERB 动词","cn":"用管子输送，用管道运输（液体或气体）","en":"If liquid or gas is piped somewhere, it is transferred from one place to another through a pipe.","ex":{"en":"The heated gas is piped through a coil surrounded by water","cn":"受热气体通过水中的盘管输送。"}},{"pos":"VERB 动词","cn":"（尤指儿童）用尖嗓子说","en":"If someone, especially a child, pipes something, they say it in a high-pitched voice.","ex":{"en":"'But I want to help,' Bessie piped.","cn":"贝茜尖声说：“但我想去帮忙。”"}},{"pos":"N-COUNT 可数名词","cn":"（一些计算机系统中用来在程序间传送信息的）管道","en":"In some computer systems, a pipe is a method of passing information from one program to another."},{"pos":"","cn":"","en":"相关词组：pipe down pipe up"}]},"examples":[{"en":"‘I know the answer,’ piped up a voice at the back of the room. “","cn":"我知道答案。”房间后边有个声音叫起来。"},{"en":"Passengers were piped aboard ship at the start of the cruise.","cn":"游客在管乐迎宾曲中登船开始水上游。"}]},"pile":{"media":{"uk":"media/uk/pile__gb_1.mp3","us":"media/us/pile__us_1.mp3","img":["media/ldoce/img/pile.jpg"]},"oxford":{"phon":"paɪl","pos":"noun","senses":[{"en":"a number of things that have been placed on top of each other","cn":"摞；垛；沓","g":"[countable]","ex":{"en":"a pile of clothes/paper","cn":"一摞衣服／纸"}},{"en":"a mass of something that is high in the middle and wider at the bottom than at the top","cn":"堆；成堆的东西","g":"[countable]","ex":{"en":"piles of dirty washing","cn":"成堆待洗的脏衣物"}},{"en":"a lot of something","cn":"大量；许多","g":"[countable, usually plural]","lab":"informal","ex":{"en":"He made a pile of cash on the sale of his house.","cn":"他卖掉房子，大赚了一笔。"}},{"en":"the short threads, pieces of wool, etc. that form the soft surface of carpets and some types of cloth such as velvet","cn":"绒头；绒毛","g":"[uncountable, singular]","ex":{"en":"a deep-pile carpet","cn":"一块厚绒地毯"}},{"en":"a large wooden, metal or stone post that is fixed into the ground and used to support a building, bridge, etc.","cn":"桩；桩柱","g":"[countable]"},{"en":"a large impressive building","cn":"宏伟建筑物","g":"[countable]","lab":"formal or humorous","ex":{"en":"a Victorian pile built as a private hospital","cn":"一座维多利亚时代的建筑堆，建为私人医院"}},{"en":"to put things one on top of another; to form a pile","cn":"堆放；摞起；叠放","g":"[transitive]","ex":{"en":"She piled the boxes one on top of the other.","cn":"她把盒子一个个地摞起来。"},"pos":"verb"},{"en":"to put something on/into something; to load something with something","cn":"放置；装入","g":"[transitive]","ex":{"en":"The sofa was piled high with cushions.","cn":"沙发上高高地堆着一些垫子。"},"pos":"verb"},{"en":"to go somewhere quickly without order or control","cn":"蜂拥；拥挤","g":"[intransitive]","lab":"informal","ex":{"en":"The coach finally arrived and we all piled on.","cn":"长途汽车终于开来了，我们一拥而上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（上窄下宽的）堆","en":"A pile of things is a mass of them that is high in the middle and has sloping sides.","ex":{"en":"...a pile of sand","cn":"一堆沙子"}},{"pos":"N-COUNT 可数名词","cn":"（一个压着一个摆放整齐的）叠，摞","en":"A pile of things is a quantity of things that have been put neatly somewhere so that each thing is on top of the one below.","ex":{"en":"...a pile of boxes","cn":"一叠盒子"}},{"pos":"VERB 动词","cn":"堆放；堆积；叠架","en":"If you pile things somewhere, you put them there so that they form a pile.","ex":{"en":"He was piling clothes into the suitcase","cn":"他在把衣服一件件叠放进手提箱中。"}},{"pos":"VERB 动词","cn":"成堆地盖住（或装满）","en":"If something is piled with things, it is covered or filled with piles of things.","ex":{"en":"Tables were piled high with local produce.","cn":"桌上高高堆放着当地的农产品。"}},{"pos":"QUANT 数量词","cn":"一大堆；大量","en":"If you talk about a pile of something or piles of something, you mean a large amount of it.","ex":{"en":"I've got a pile of questions afterwards for you.","cn":"我有一大堆的问题等着过后问你。"}},{"pos":"VERB 动词","cn":"拥进/拥出；挤进/挤出","en":"If a group of people pile into or out of a vehicle, they all get into it or out of it in a disorganized way.","ex":{"en":"They all piled into Jerrold's car","cn":"他们一窝蜂地挤进杰罗尔德的车里。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指富人或要人居住的）高大宏伟的建筑物","en":"You can refer to a large impressive building as a pile, especially when it is the home of a rich important person.","ex":{"en":"...some stately pile in the country.","cn":"乡下某座恢宏气派的建筑"}},{"pos":"N-COUNT 可数名词","cn":"（房屋和桥梁的）桩，桩柱","en":"Piles are wooden, concrete, or metal posts which are pushed into the ground and on which buildings or bridges are built. Piles are often used in very wet areas so that the buildings do not flood.","ex":{"en":"...settlements of wooden houses, set on piles along the shore.","cn":"建在沿岸桩柱上的木制房屋居住区"}},{"pos":"N-PLURAL 复数名词","cn":"痔疮","en":"Piles are painful swellings that can appear in the veins inside a person's anus."},{"pos":"N-SING 单数名词","cn":"（地毯或织物的）绒面，绒毛，绒头","en":"The pile of a carpet or of a fabric such as velvet is its soft surface. It consists of a lot of little threads standing on end.","ex":{"en":"...the carpet's thick pile.","cn":"地毯的厚绒"}},{"pos":"PHRASE 短语","cn":"处于（社会或某组织的）下层/上层","en":"Someone who is at the bottom of the pile is low down in society or low down in an organization. Someone who is at the top of the pile is high up in society or high up in an organization."},{"pos":"","cn":"","en":"相关词组：pile up"}]},"examples":[{"en":"The German team piled on the pressure in the last 15 minutes.","cn":"在最后 15 分钟，德国队施加了强大的压力。"},{"en":"Bosses piled on the agony with threats of more job losses.","cn":"老板威胁要削减更多的职位，令情况更加恶化。"}]},"picks":{"oxford":{"phon":"pɪk","pos":"verb","senses":[{"en":"( rather informal ) to choose sb/sth from a group of people or things","cn":"选择；挑选"},{"en":"to take flowers, fruit, etc. from the plant or the tree where they are growing","cn":"采；摘"}]}},"picked":{"oxford":{"phon":"pɪk","pos":"verb","senses":[{"en":"( rather informal ) to choose sb/sth from a group of people or things","cn":"选择；挑选"},{"en":"to take flowers, fruit, etc. from the plant or the tree where they are growing","cn":"采；摘"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41picked.mp3","us":"media/ldoce/hwd/ame/a/ld41picked.mp3"}},"piccolos":{"oxford":{"phon":"ˈpɪkələʊ","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group, like a small flute that plays high notes","cn":"短笛"}]}},"pinata":{"oxford":{"phon":"pɪnˈjɑːtə","pos":"noun","senses":[{"en":"a brightly decorated figure, filled with toys and sweets, which children try to hit with a stick with their eyes covered in order to break it open, as a party game","cn":"彩色礼品包（内装玩具和糖果，儿童聚会玩游戏时蒙眼用小棍戳破）"}]}},"pictures":{"oxford":{"phon":"ˈpɪktʃə(r)","pos":"noun","senses":[{"en":"a painting or drawing, etc. that shows a scene, a person or thing","cn":"图画；绘画"},{"en":"a photograph","cn":"相片；照片"}]}},"piled":{"oxford":{"phon":"paɪl","pos":"noun","senses":[{"en":"a number of things that have been placed on top of each other","cn":"摞；垛；沓"},{"en":"a mass of sth that is high in the middle and wider at the bottom than at the top","cn":"堆；成堆的东西"}]}},"pieces":{"oxford":{"phon":"piːs","pos":"noun","senses":[{"en":"( used especially with of and uncountable nouns","cn":"尤与 of 和不可数名词连用 ) an amount of sth that has been cut or separated from the rest of it; a standard amount of sth 片；块；段；截；标"},{"en":"one of the bits or parts that sth breaks into","cn":"碎片；碎块"}]}},"pictured":{"oxford":{"phon":"ˈpɪktʃə(r)","pos":"noun","senses":[{"en":"a painting or drawing, etc. that shows a scene, a person or thing","cn":"图画；绘画"},{"en":"a photograph","cn":"相片；照片"}]}},"picking":{"oxford":{"phon":"pɪk","pos":"verb","senses":[{"en":"( rather informal ) to choose sb/sth from a group of people or things","cn":"选择；挑选"},{"en":"to take flowers, fruit, etc. from the plant or the tree where they are growing","cn":"采；摘"}]}},"pitches":{"oxford":{"phon":"pɪtʃ","pos":"noun","senses":[{"en":"an area of ground specially prepared and marked for playing a sports game （","cn":"体育比赛的）场地；球场"},{"en":"how high or low a sound is, especially a musical note （","cn":"尤指乐音的）音高"}]}},"pineapple":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"菠萝；凤梨","en":"A pineapple is a large oval fruit that grows in hot countries. It is sweet, juicy, and yellow inside. It has a thick brownish skin."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large yellow-brown tropical fruit or its sweet juicy yellow flesh","cn":"菠萝﹐凤梨"}]},"collocations":{"phrases":["ADJ. juicy, sweet","PINEAPPLE + NOUN chunks, rings a tin of pineapple chunks •"]},"media":{"img":["media/ldoce/img/pineapple.jpg","media/thumb/pineapple.jpg"],"uk":"media/ldoce/hwd/bre/3/brelasdepineapple.mp3","us":"media/ldoce/hwd/ame/c/pineapple.mp3"},"examples":[{"en":"a tin of pineapple chunks","cn":"一罐菠萝块"},{"en":"fresh pineapple","cn":"新鲜菠萝"}],"oxford":{"phon":"ˈpaɪnæpl","pos":"noun","senses":[{"en":"a large tropical fruit with thick rough skin and stiff leaves on top, that is sweet and yellow inside with a lot of juice","cn":"菠萝；凤梨","ex":{"en":"fresh pineapple","cn":"新鲜菠萝"}}]}},"pitfall":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"隐患；陷阱；圈套","en":"The pitfalls involved in a particular activity or situation are the things that may go wrong or may cause problems.","ex":{"en":"The pitfalls of working abroad are numerous","cn":"到国外工作存在许多陷阱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a problem or difficulty that is likely to happen in a particular job, course of action, or activity 〔","cn":"可能出现的〕问题﹐困难﹔隐患﹔陷阱"}]},"vocab":{"pos":"n","senses":[{"en":"A pitfall is a trap or difficulty you didn't see. A possible pitfall for high school seniors is not working hard after they know they've already been accepted into college."}]},"collocations":{"phrases":["ADJ. obvious | common | hidden | possible, potential, unforeseen We need to be alert to potential pitfalls.","VERB + PITFALL be fraught with, be full of, have, hold Trading in a foreign country can be fraught with pitfalls. | avoid | overcome","PITFALL + VERB await sb Numerous pitfalls await unsuspecting investors.","PREP. ~ for Buying property holds many pitfalls for the unwary. | ~ in pitfalls in the interpretation of statistics"]},"media":{"uk":"media/ldoce/hwd/bre/9/pitfall0205.mp3","us":"media/ldoce/hwd/ame/0/pitfall.mp3"},"examples":[{"en":"the potential pitfalls of buying a house","cn":"购买房屋可能遇到的圈套"},{"en":"He gave me advice on how to avoid the pitfalls of the legal process.","cn":"他给了我一些建议﹐教我如何避免诉讼过程中的隐患。"}],"oxford":{"phon":"ˈpɪtfɔːl","pos":"noun","senses":[{"en":"a danger or difficulty, especially one that is hidden or not obvious at first","cn":"危险；困难；（尤指）陷阱，隐患","ex":{"en":"the potential pitfalls of buying a house","cn":"购买房屋可能遇到的圈套"}}]}},"picnic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"野餐；户外用餐","en":"When people have a picnic, they eat a meal out of doors, usually in a field or a forest, or at the beach.","ex":{"en":"We're going on a picnic tomorrow","cn":"我们明天去野餐。"}},{"pos":"VERB 动词","cn":"野餐","en":"When people picnic somewhere, they have a picnic.","ex":{"en":"Afterwards, we picnicked on the riverbank.","cn":"之后，我们在河边野餐。"}},{"pos":"PHRASE 短语","cn":"不是件轻松（或愉快）的事","en":"If you say that an experience, task, or activity is no picnic, you mean that it is quite difficult or unpleasant.","ex":{"en":"Emigrating is no picnic.","cn":"移民不是件轻松的事。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a meal that you eat in the morning","cn":""},{"en":"a meal that you eat in the late morning, instead of breakfast or lunch","cn":""},{"en":"a meal that you eat in the middle of the day","cn":""}]},"collocations":{"phrases":["VERB + PICNIC go for/on, have Lets have a picnic down by the river. | make Will you help me make a picnic? | bring, take We took a picnic an","PICNIC + NOUN basket, blanket, hamper, rug, set, table | lunch, tea | area, place, site, spot"]},"media":{"img":["media/ldoce/img/picnic.jpg"],"uk":"media/ldoce/hwd/bre/e/picnic_n0205.mp3","us":"media/ldoce/hwd/ame/e/picnic1.mp3"},"examples":[{"en":"Bringing up a family when you're unemployed is no picnic.","cn":"失了业还要养家可不是容易的事。"},{"en":"It's a nice day. Let's go for a picnic.","cn":"天气不错；咱们去野餐吧。"}],"oxford":{"phon":"ˈpɪknɪk","pos":"noun","senses":[{"en":"an occasion when people pack a meal and take it to eat outdoors, especially in the countryside","cn":"野餐","ex":{"en":"It's a nice day. Let's go for a picnic.","cn":"天气不错；咱们去野餐吧。"}},{"en":"the meal, usually consisting of sandwiches, salad and fruit, etc. that you take with you when you go on a picnic","cn":"野餐食物","ex":{"en":"Let's eat our picnic by the lake.","cn":"咱们到湖边去吃野餐吧。"}},{"en":"to have a picnic","cn":"野餐","ex":{"en":"No picnicking allowed (= on a sign)","cn":"禁止野餐"},"pos":"verb"}]}},"pickle":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"泡菜；腌菜","en":"Pickles are vegetables or fruit, sometimes cut into pieces, which have been kept in vinegar or salt water for a long time so that they have a strong, sharp taste.","ex":{"en":"Another strong Yorkshire country tradition is making pickles and chutneys.","cn":"另一个在约克郡盛行的民间传统是做泡菜和酸辣酱。"}},{"pos":"N-MASS 物质名词","cn":"菜酱","en":"Pickle is a cold spicy sauce with pieces of vegetables and fruit in it.","ex":{"en":"...jars of pickle.","cn":"一罐罐菜酱"}},{"pos":"VERB 动词","cn":"（以醋或盐水）泡制，腌制，腌渍","en":"When you pickle food, you keep it in vinegar or salt water so that it does not go bad and it develops a strong, sharp taste.","ex":{"en":"Select your favourite fruit or veg and pickle them while they are still fresh","cn":"挑选最喜欢的水果或蔬菜，趁着新鲜把它们腌起来。"}},{"pos":"N-SING 单数名词","cn":"困境；逆境；窘境","en":"If you are in a pickle, you are in a difficult and awkward situation.","ex":{"en":"Companies find themselves in a pickle when their markets change","cn":"公司在市场发生变化时会发现自己身陷困境。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thick cold sauce that is made from pieces of vegetables preserved in vinegar . It is usually eaten with cold meat or cheese","cn":"腌菜﹐泡菜"},{"en":"a cucumber preserved in vinegar or salt water, or a piece of this","cn":"醋渍黄瓜（片）﹔腌黄瓜（片）"},{"en":"to be in a very difficult situation and not know what to do","cn":"处于困境﹔处于困惑"}]},"collocations":{"phrases":["ADJ. sweet | dill | lime","QUANT. jar","PHRASES and/with pickle/pickles a cheese and pickle sandwich"]},"media":{"img":["media/ldoce/img/pickles.jpg"],"uk":"media/ldoce/hwd/bre/c/pickle_n0205.mp3","us":"media/ldoce/hwd/ame/1/pickle1.mp3"},"examples":[{"en":"a selection of cold meats and pickles","cn":"精选的冷肉和腌菜"},{"en":"cheese and pickle sandwiches","cn":"干酪腌菜三明治"}],"oxford":{"phon":"ˈpɪkl","pos":"noun","senses":[{"en":"a vegetable that has been preserved in vinegar or salt water and has a strong taste, served cold with meat, salads, etc.","cn":"泡菜；腌菜","g":"[countable, usually plural]","lab":"British English"},{"en":"a cold thick spicy sauce made from fruit and vegetables that have been boiled, often sold in jars and served with meat, cheese, etc.","cn":"菜酱","g":"[uncountable]","lab":"British English","ex":{"en":"a cheese and pickle sandwich","cn":"奶酪果酱三明治"}},{"en":"a small cucumber that has been preserved in vinegar before being eaten","cn":"醋泡小黄瓜","g":"[uncountable, countable]","lab":"North American English"},{"en":"to preserve food in vinegar or salt water","cn":"腌渍","pos":"verb"}]}},"pillion":{"collins":{"senses":[{"pos":"ADV 副词","cn":"在（摩托车或自行车的）后座上","en":"If someone rides pillion on a motorcycle or bicycle, they sit behind the person who is controlling it.","ex":{"en":"She rode pillion on her son's motor bike.","cn":"她坐在儿子摩托车的后座上。"}},{"pos":"N-COUNT 可数名词","cn":"（摩托车的）后座","en":"On a motorcycle, the pillion is the seat or part behind the rider.","ex":{"en":"As a learner rider you must not carry a pillion passenger.","cn":"作为摩托车初学者，切勿后座载人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the seat behind the driver of a motorcycle","cn":"摩托车后座"}]},"collocations":{"phrases":["VERB + PILLION ride He drove his motorbike, with me riding pillion.","PILLION + NOUN seat | passenger, rider","PREP. on the ~ I made the whole journey on the pillion."]},"media":{"uk":"media/ldoce/hwd/bre/f/pillion0205.mp3","us":"media/ldoce/hwd/ame/6/pillion.mp3"},"examples":[{"en":"a pillion passenger/seat","cn":"摩托车后座乘客；摩托车后座"},{"en":"to ride pillion","cn":"坐在摩托车的后座上"}],"oxford":{"phon":"ˈpɪliən","pos":"adverb","senses":[{"en":"sitting on a seat for a passenger behind the driver of a motorcycle","cn":"摩托车后座","ex":{"en":"He drove his motorbike, with me riding pillion.","cn":"他开摩托车，我坐在后座上。"}},{"en":"a seat for a passenger behind the driver of a motorcycle","cn":"摩托车后座","ex":{"en":"a pillion passenger/seat","cn":"摩托车后座乘客；摩托车后座"},"pos":"noun"}]}},"pint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"品脱（液量单位，英制中等于0.568升或1/8英国加仑，美制中等于0.473升或1/8美国加仑）","en":"A pint is a unit of measurement for liquids. In Britain, it is equal to 568 cubic centimetres or one eighth of an imperial gallon. In America, it is equal to 473 cubic centimetres or one eighth of an American gallon.","ex":{"en":"...a pint of milk","cn":"一品脱牛奶"}},{"pos":"N-COUNT 可数名词","cn":"一品脱啤酒","en":"If you go for a pint, you go to the pub to drink a pint of beer or more.","ex":{"en":"He sits down and reads the paper, then goes out for a pint.","cn":"他会坐下读报，然后出去喝杯啤酒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a unit for measuring an amount of liquid, especially beer or milk. In Britain a pint is equal to 0.568 litres, and in the US it is equal to 0.473 litres","cn":"品脱〔液量单位﹐尤用于啤酒或牛奶。在英国一品脱合0.568升﹐而在美国一品脱合0.473升〕"},{"en":"a pint of beer, especially one that you drink in a bar 〔","cn":"尤指在酒吧喝的〕一品脱啤酒"}]},"collocations":{"phrases":["VERB + PINT consume, drink, have | sip | down, drain, finish, knock back, sink He could sink a pint faster than anyone else I knew. | draw (","PINT + NOUN glass"]},"media":{"uk":"media/ldoce/hwd/bre/9/pint0205.mp3","us":"media/ldoce/hwd/ame/c/pint.mp3"},"examples":[{"en":"We'd better get a couple of extra pints (= of milk) tomorrow.","cn":"明天我们最好再多买几品脱牛奶。"},{"en":"Do you want to go for a pint later?","cn":"待会儿你想去喝杯啤酒吗？"}],"oxford":{"phon":"paɪnt","pos":"noun","senses":[{"en":"a unit for measuring liquids and some dry goods, equal to 0.568 of a litre in the UK and some other countries, and 0.473 of a litre in the US. There are 8 pints in a gallon","cn":"品脱（容量单位，在英国等国家约合 0.568 升，在美国约合 0.473 升；8 品脱合一加仑）","ex":{"en":"a pint of beer/milk","cn":"一品脱啤酒／牛奶"}},{"en":"a pint of beer (especially in a pub)","cn":"一品脱啤酒（尤用于酒吧）","lab":"British English","ex":{"en":"Do you want to go for a pint later?","cn":"待会儿你想去喝杯啤酒吗？"}}]}},"pinch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"捏；拧；掐；夹","en":"If you pinch a part of someone's body, you take a piece of their skin between your thumb and first finger and give it a short squeeze.","ex":{"en":"She pinched his arm as hard as she could","cn":"她使出浑身的力气拧他的胳膊。"}},{"pos":"N-COUNT 可数名词","cn":"（一）撮；少量","en":"A pinch of an ingredient such as salt is the amount of it that you can hold between your thumb and your first finger. to take something with a pinch of salt→see: ;","ex":{"en":"Put all the ingredients, including a pinch of salt, into a food processor.","cn":"把包括一撮盐在内的所有配料放入食品加工机。"}},{"pos":"VERB 动词","cn":"偷取，偷盗（尤指不贵重的物品）","en":"To pinch something, especially something of little value, means to steal it.","ex":{"en":"Do you remember when I pinched your glasses?","cn":"你还记得我偷你眼镜的事儿吗？"}},{"pos":"PHRASE 短语","cn":"必要时；在紧要关头","en":"If you say that something is possible at a pinch, or in American English if you say that something is possible in a pinch, you mean that it would be possible if it was necessary, but it might not be very comfortable or convenient.","ex":{"en":"Six people, and more at a pinch, could be seated comfortably at the table.","cn":"这张桌子可以很舒服地坐6个人，而且必要时多坐几个也不会挤。"}},{"pos":"PHRASE 短语","cn":"感到手头拮据；感到囊中羞涩","en":"If a person or company is feeling the pinch, they do not have as much money as they used to, and so they cannot buy the things they would like to buy.","ex":{"en":"Consumers are spending less and traders are feeling the pinch.","cn":"消费者支出在减少，商人感觉手头拮据。"}},{"pos":"PHRASE 短语","cn":"身处困境；处境艰难","en":"If you are in a pinch, you are in a difficult situation.","ex":{"en":"I'd trust her in a pinch","cn":"身处困境时，我信任她。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if part of your body hurts, it feels painful","cn":""},{"en":"to hurt with a continuous pain","cn":""},{"en":"to feel a bad pain that comes and goes again in a regular and continuous way","cn":""}]},"collocations":{"phrases":["ADV. firmly | gently | sharply | playfully | together Apply pressure to the nose by pinching the nostrils firmly together.","PREP. between He pinched the leaf between his thumb and forefinger. | on He pinched me sharply on the arm. 2 be too tight","ADV. badly My shoes were pinching badly."]},"media":{"uk":"media/ldoce/hwd/bre/3/pinch_n0205.mp3","us":"media/ldoce/hwd/ame/f/pinch1.mp3"},"examples":[{"en":"( figurative ) She had to pinch herself to make sure she was not dreaming.","cn":"她不得不掐一下自己，弄清楚自己不是在做梦。"},{"en":"Higher interest rates are already pinching the housing industry.","cn":"提高利率已使住房产业不堪负荷。"}],"oxford":{"phon":"pɪntʃ","pos":"verb","senses":[{"en":"to take a piece of somebody’s skin and press it together hard with your thumb and the finger next to it","cn":"拧；捏；掐","g":"[transitive]","lab":"figurative","sc":"press","ex":{"en":"My sister's always pinching me and it really hurts.","cn":"我姐姐老拧我，真的很痛。"}},{"en":"to hold something tightly between the thumb and finger or between two things that are pressed together","cn":"捏住；夹紧","g":"[transitive]","sc":"press","ex":{"en":"Pinch the nostrils together between your thumb and finger to stop the bleeding.","cn":"用手指捏住鼻孔止血。"}},{"en":"to place the thumb and a finger of one hand on the screen of an electronic device such as a mobile phone or small computer and move them together or apart, to make the image on the screen appear smaller or larger","cn":"（在手机等电子装置上）两指张合以放大（或缩小）图像","g":"[intransitive, transitive]","sc":"press","ex":{"en":"You can pinch and zoom in.","cn":"您可以捏合并放大。"}},{"en":"if something such as a shoe pinches part of your body, it hurts you because it is too tight","cn":"夹（脚）；夹痛","g":"[intransitive, transitive]","sc":"of a shoe","ex":{"en":"These new shoes pinch.","cn":"这双新鞋夹脚。"}},{"en":"to steal something, especially something small and not very valuable","cn":"（尤指）小偷小摸","g":"[transitive]","lab":"British English, informal，，","sc":"steal","ex":{"en":"Kids have been pinching our apples again.","cn":"孩子们又开始捏我们的苹果了。"}},{"en":"to cost a person or an organization a lot of money or more than they can spend","cn":"使花费过多；使入不敷出","g":"[transitive]","sc":"cost too much","ex":{"en":"Higher interest rates are already pinching the housing industry.","cn":"提高利率已使住房产业不堪负荷。"}},{"en":"to arrest somebody","cn":"逮捕；抓捕","g":"[transitive]","lab":"British English, old-fashioned, informal，，，，","sc":"arrest","ex":{"en":"I was pinched for dangerous driving.","cn":"我因危险驾驶而被抓。"}},{"en":"an act of pressing a part of somebody’s skin together hard with your thumb and finger, especially in order to hurt them","cn":"拧；捏；掐","sc":"act of pressing","ex":{"en":"She gave him a pinch on the arm to wake him up.","cn":"她拧了一下他的胳膊把他唤醒。"},"pos":"noun"},{"en":"the amount of something that you can hold between your finger and thumb","cn":"一撮","sc":"small amount","ex":{"en":"Add a pinch of salt to the mixture and stir well.","cn":"在混合料中加一撮盐，搅拌均匀。"},"pos":"noun"}]}},"pistol":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手枪","en":"A pistol is a small gun."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small gun you can use with one hand","cn":"手枪"}]},"collocations":{"phrases":["ADJ. automatic, machine, semi-automatic | unlicensed | loaded | air, water | duelling, starting runners waiting for the starting pistol","VERB + PISTOL load | draw, produce He drew his pistol, aimed and fired. | cock | aim, level, point, raise | fire | carry There were two of t","PISTOL + NOUN shot","PHRASES at pistol point He was robbed in his hotel at pistol point."]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdepistol.mp3","us":"media/ldoce/hwd/ame/2/pistil.mp3"},"examples":[{"en":"a starting pistol (= used to signal the start of a race)","cn":"发令枪"},{"en":"an automatic pistol","cn":"自动手枪"}],"oxford":{"phon":"ˈpɪstl","pos":"noun","senses":[{"en":"a small gun that you can hold and fire with one hand","cn":"手枪","ex":{"en":"The assassin shot the two men with a 9mm automatic pistol.","cn":"行刺者用9毫米自动手枪向那两个男人开枪。"}}]}},"pioneer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"先驱；先锋；创始人；倡导者","en":"Someone who is referred to as a pioneer in a particular area of activity is one of the first people to be involved in it and develop it.","ex":{"en":"...one of the leading pioneers of British photo journalism","cn":"英国新闻摄影界的领军人物之一"}},{"pos":"VERB 动词","cn":"开创；倡导","en":"Someone who pioneers a new activity, invention, or process is one of the first people to do it.","ex":{"en":"...Professor Alec Jeffreys, who invented and pioneered DNA tests","cn":"发明和倡导DNA检测的亚历克·杰弗里斯教授"}},{"pos":"N-COUNT 可数名词","cn":"拓荒者；开拓者；开发者","en":"Pioneers are people who leave their own country or the place where they were living, and go and live in a place that has not been lived in before.","ex":{"en":"...abandoned settlements of early European pioneers.","cn":"已废弃的早期欧洲拓荒者的定居点"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is important in the early development of something, and whose work or ideas are later developed by other people","cn":"先驱﹐先锋﹐创始人"},{"en":"one of the first people to travel to a new country or area and begin living there, farming etc","cn":"拓荒者﹐开拓者﹐开发者"},{"en":"to be the first to do something, especially something good or successful, which may encourage others to do something similar","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A pioneer is one of the first settlers in a new place. If you desperately want to experience life in space, maybe you will be one of the pioneers who live in the first moon settlement."}]},"collocations":{"phrases":["ADJ. early | true","PIONEER + NOUN spirit | missionary","PREP. ~ in one of the early pioneers in plastic surgery"]},"media":{"uk":"media/ldoce/hwd/bre/2/pioneer_n0205.mp3","us":"media/ldoce/hwd/ame/6/pioneer1.mp3"},"examples":[{"en":"a new technique pioneered by surgeons in a London hospital","cn":"由伦敦一家医院的外科医生率先采用的新技术"},{"en":"a pioneer in the field of microsurgery","cn":"显微外科领域的创始人"}],"oxford":{"phon":"ˌpaɪəˈnɪə(r)","pos":"noun","senses":[{"en":"a person who is the first to study and develop a particular area of knowledge, culture, etc. that other people then continue to develop","cn":"先锋；先驱；带头人","ex":{"en":"a pioneer in the field of microsurgery","cn":"显微外科领域的创始人"}},{"en":"one of the first people to go to a particular place, especially in order to live and work there","cn":"开发者；拓荒者","ex":{"en":"Early pioneers settled on both sides of the Maple River.","cn":"早期的拓荒者在枫河两岸定居。"}},{"en":"when somebody pioneers something, they are one of the first people to do, discover or use something new","cn":"当开拓者；做先锋；倡导","ex":{"en":"a new technique pioneered by surgeons in a London hospital","cn":"由伦敦一家医院的外科医生率先采用的新技术"},"pos":"verb"}]}},"picket":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常指工会成员）在…设置罢工纠察队，在…外抗议","en":"When a group of people, usually trade union members, picket a place of work, they stand outside it in order to protest about something, to prevent people from going in, or to persuade the workers to join a strike.","ex":{"en":"The miners went on strike and picketed the power stations","cn":"矿工开始罢工，并在发电站周围设置了纠察队。"}},{"pos":"N-COUNT 可数名词","cn":"罢工纠察队员；示威者；抗议者","en":"Pickets are people who are picketing a place of work.","ex":{"en":"Ten hotels were damaged by pickets in the weekend strike of hotel workers","cn":"在宾馆员工周末举行的罢工中，有10家宾馆遭到纠察队员的破坏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a group of people stand or march in front of a shop, factory, government building etc to protest about something or to stop people from going in during a strike 〔","cn":"罢工时设置的〕纠察队，纠察线"},{"en":"a person or the group of people involved in a picket","cn":"纠察队员"},{"en":"a soldier or a group of soldiers with the special duty of guarding a military camp","cn":"哨兵﹔哨兵队"}]},"collocations":{"phrases":["ADJ. mass | flying Flying pickets arrived from all over the country.","VERB + PICKET organize They organized a mass picket of the governor's palace.","PICKET + NOUN duty | line Abuse was hurled at workers who crossed the picket line."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdepicket1.mp3","us":"media/ldoce/hwd/ame/c/picket1.mp3"},"examples":[{"en":"Striking workers picketed outside the gates.","cn":"罢工工人围在大门外担任纠察（禁止出入）。"},{"en":"I was on picket duty at the time.","cn":"当时我正执行罢工的纠察工作。"}],"oxford":{"phon":"ˈpɪkɪt","pos":"noun","senses":[{"en":"a person or group of people who stand outside the entrance to a building in order to protest about something, especially in order to stop people from entering a factory, etc. during a strike; an occasion at which this happens","cn":"（罢工期间纠察妥协分子的）纠察员，纠察队；罢工警戒","ex":{"en":"Five pickets were arrested by police.","cn":"五名纠察队员被警方逮捕。"}},{"en":"a soldier or group of soldiers guarding a military base","cn":"（军营的）警戒哨，警戒队，哨兵"},{"en":"a pointed piece of wood that is fixed in the ground, especially as part of a fence","cn":"（尤指栅栏的）尖木桩，尖板条","ex":{"en":"a picket fence","cn":"尖板条栅栏"}},{"en":"to stand outside somewhere such as your place of work to protest about something or to try and persuade people to join a strike","cn":"在…外抗议；进行罢工纠察","ex":{"en":"200 workers were picketing the factory.","cn":"200 名工人在工厂外罢工抗议。"},"pos":"verb"}]}},"pinnacle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"尖锥形石；尖岩","en":"A pinnacle is a pointed piece of stone or rock that is high above the ground.","ex":{"en":"A walker fell 80ft from a rocky pinnacle.","cn":"一位徒步者从一块80英尺高的尖锥形岩石上摔了下来。"}},{"pos":"N-COUNT 可数名词","cn":"顶峰；极点；顶点","en":"If someone reaches the pinnacle of their career or the pinnacle of a particular area of life, they are at the highest point of it.","ex":{"en":"John Major has reached the pinnacle of British politics","cn":"约翰·梅杰已攀上了英国政界的顶峰。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the most successful, powerful, exciting etc part of something","cn":"巅峰﹔顶点﹔鼎盛时期"},{"en":"a high mountain top","cn":"山巅﹐山峰﹐山顶"},{"en":"a pointed stone decoration, like a small tower, on a building such as a church or castle 〔","cn":"教堂或城堡等上作装饰用的〕尖顶﹐小尖塔"}]},"vocab":{"pos":"n v","senses":[{"en":"Going as far into the sky as you can go on foot, you'll reach the highest point, or pinnacle, of the Himalayas. A successful climb like that might also become the pinnacle, or peak, of your success."}]},"collocations":{"phrases":["VERB + PINNACLE reach He had reached the pinnacle of his military career.","PREP. at the ~ of She is at the pinnacle of her profession."]},"media":{"uk":"media/ldoce/hwd/bre/4/pinnacle0205.mp3","us":"media/ldoce/hwd/ame/f/pinnacle.mp3"},"examples":[{"en":"the pinnacle of her career","cn":"她事业的顶峰"},{"en":"She had reached the pinnacle of her political career.","cn":"她已经达到政治生涯的顶峰。"}],"oxford":{"phon":"ˈpɪnəkl","pos":"noun","senses":[{"en":"the most important or successful part of something","cn":"顶点；顶峰；鼎盛时期","g":"[usually singular]","ex":{"en":"the pinnacle of her career","cn":"她事业的顶峰"}},{"en":"a small pointed stone decoration built on the roof of a building","cn":"（建筑物）尖顶","ex":{"en":"We could just make out the pinnacles of the cathedral in the distance.","cn":"我们只能看到远处大教堂的尖顶。"}},{"en":"a high pointed piece of rock, especially at the top of a mountain","cn":"（尤指山顶的）尖岩，兀立岩石"}]}},"pipeline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（常指埋于地下的石油或燃气）管道，管线","en":"A pipeline is a large pipe which is used for carrying oil or gas over a long distance, often underground.","ex":{"en":"A consortium plans to build a natural-gas pipeline from Russia to supply eastern Germany.","cn":"一家财团计划建造一条从俄罗斯向德国东部输送天然气的管道。"}},{"pos":"PHRASE 短语","cn":"在筹备中；在进行中","en":"If something is in the pipeline, it has already been planned or begun.","ex":{"en":"Already in the pipeline is a 2.9 per cent pay increase for teachers.","cn":"教师的工资将上调2.9%，此事正在运作中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if something such as a new product or a change is in the pipeline , it is being planned and prepared and it will be ready soon","cn":""},{"en":"if something such as a product is in the planning stages , it is being planned, but the final details have not yet been decided","cn":""},{"en":"if something new, interesting, strange, or dishonest is afoot , someone is planning it, especially secretly","cn":""}]},"collocations":{"phrases":["ADJ. gas, oil, water","VERB + PIPELINE build, construct, lay","PIPELINE + VERB supply sth The pipeline supplies Jordan with 15 per cent of its crude oil. | pass through sth, run through sth The pipeline ","PIPELINE + NOUN network, system","PREP. in the ~ (figurative) (= being discussed or prepared) Important changes are already in the pipeline. | ~ across a pipeline across the "]},"media":{"uk":"media/ldoce/hwd/bre/4/pipeline0205.mp3","us":"media/ldoce/hwd/ame/f/pipeline.mp3"},"examples":[{"en":"More job losses are in the pipeline.","cn":"将会有更多人被裁。"}],"oxford":{"phon":"ˈpaɪplaɪn","pos":"noun","senses":[{"en":"a series of pipes that are usually underground and are used for carrying oil, gas, etc. over long distances","cn":"输油管道，输气管道，输送管线（通常指地下的）","ex":{"en":"There are plans to lay a gas pipeline through the region.","cn":"计划在这个地区铺设输气管道。"}}]}},"pilgrimage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"朝圣；朝觐","en":"If you make a pilgrimage to a holy place, you go there for a religious reason.","ex":{"en":"...the pilgrimage to Mecca.","cn":"去麦加的朝圣"}},{"pos":"N-COUNT 可数名词","cn":"拜谒；重要旅程","en":"A pilgrimage is a journey that someone makes to a place that is very important to them.","ex":{"en":"...a private pilgrimage to family graves","cn":"私下前往家族墓地的拜谒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when you travel from one place to another – used especially about travelling a long distance, or travelling somewhere regularly","cn":""},{"en":"a journey to visit a place","cn":""},{"en":"a journey for pleasure, during which you visit several different towns, areas etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A pilgrimage is a journey to a sacred place. People make pilgrimages to places like Jerusalem, Bethlehem, and Dharamsala as part of their religious or spiritual practice."}]},"collocations":{"phrases":["ADJ. annual | spiritual","VERB + PILGRIMAGE go on, make","PILGRIMAGE + NOUN route","PREP. during a/the ~ There was a ban on political protests during the pilgrimage. | on a/the ~ He was on his annual pilgrimage to Mecca when","PHRASES a centre/place of pilgrimage, an object of pilgrimage The shrine was an object of pilgrimage."]},"media":{"uk":"media/ldoce/hwd/bre/4/pilgrimage0205.mp3","us":"media/ldoce/hwd/ame/0/pilgrimage.mp3"},"examples":[{"en":"His grave has become a place of pilgrimage.","cn":"他的陵墓成了参拜之地。"},{"en":"to go on/make a pilgrimage","cn":"前往朝圣"}],"oxford":{"phon":"ˈpɪlɡrɪmɪdʒ","pos":"noun","senses":[{"en":"a journey to a holy place for religious reasons","cn":"朝圣之旅","lab":"North American English","ex":{"en":"to go on/make a pilgrimage","cn":"前往朝圣"}},{"en":"a journey to a place that is connected with somebody/something that you admire or respect","cn":"参拜之行；瞻仰之旅","ex":{"en":"His grave has become a place of pilgrimage.","cn":"他的陵墓成了参拜之地。"}}]}}});
